INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l21','rise to fame','',NULL,'/raɪz tə feɪm/','Mendoza rose to fame very young.','门多萨很年轻就成了名。','The band rose to fame overnight.','这支乐队一夜成名。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l21','not ... until','',NULL,'/nɑːt ənˈtɪl/','Gloves were not used until 1860.','直到1860年才用上手套。','I didn''t know until yesterday.','我直到昨天才知道。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l21','be adored by','',NULL,'/bi əˈdɔːrd baɪ/','He was adored by rich and poor alike.','他受到贫富一致的爱戴。','The teacher was adored by her students.','这位老师深受学生爱戴。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l21','fall into debt','',NULL,'/fɔːl ˈɪntə det/','Little by little he fell into debt.','他渐渐债台高筑。','Many people fall into debt after big purchases.','很多人大额消费后就负债了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp1','choice','{"stem":"\"Gloves ___ introduced until 1860.\"(“直到…才”:not ... until)","options":["were not","are not","had","were"],"answer_index":0,"stem_cn":"直到1860年才用上拳套。","explanation_cn":"“直到1860年才……”用 not ... until;拳套“被引入”是被动,过去用 were not (introduced)。✓ Gloves were not introduced until 1860. ✗ were / are not / had:配不出“直到…才”的被动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp1','choice','{"stem":"\"It was ___ 1790 that Mendoza finally won the title.\"(not ... until 强调结构)","options":["until not","not till until","not until","no until"],"answer_index":2,"stem_cn":"直到1790年门多萨才终于夺冠。","explanation_cn":"强调“直到…才”用 It was not until … that …。✓ It was not until 1790 that he won. ✗ until not / not till until / no until:固定说 not until。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp1','choice','{"stem":"\"He did not become champion ___ his third try.\"(“直到…才”)","options":["since","before","from","until"],"answer_index":3,"stem_cn":"直到第三次尝试他才当上冠军。","explanation_cn":"“直到…才”用 not ... until。✓ did not become champion until his third try. ✗ since / before / from:表“直到”用 until。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp2','choice','{"stem":"\"Mendoza ___ to fame while still a teenager.\"(“成名、上升”用哪个)","options":["raise","rise","rose","raised"],"answer_index":2,"stem_cn":"门多萨十几岁就成了名。","explanation_cn":"“成名、地位上升”用 rise(过去式 rose),后面不接一个东西。✓ Mendoza rose to fame. ✗ raised(要接一个东西)/ rise / raise:这里用 rose。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp2','choice','{"stem":"\"The champion ___ his fists and the crowd cheered.\"(“举起”后接一个东西,用哪个)","options":["raise","raised","rose","rise"],"answer_index":1,"stem_cn":"冠军举起拳头,人群欢呼。","explanation_cn":"“举起(拳头)”后面接了一个东西,用 raise(过去式 raised)。✓ raised his fists. ✗ rose(后面不接东西)/ rise / raise:这里用 raised。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp2','choice','{"stem":"\"The sun ___ early on the morning of the big match.\"(“升起”用哪个)","options":["rises","raise","raised","rose"],"answer_index":3,"stem_cn":"大赛那天早上太阳升得早。","explanation_cn":"“太阳升起”用 rise(过去式 rose),后面不接东西。✓ The sun rose early. ✗ raised(要接东西)/ raise / rises(时态不对):这里用 rose。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp3','choice','{"stem":"\"Boxing was popular in England two hundred years ___.\"(从现在往前数,用哪个)","options":["since","ago","past","before"],"answer_index":1,"stem_cn":"两百年前拳击在英格兰很流行。","explanation_cn":"从“现在”往前数多少年,用 ago。✓ two hundred years ago. ✗ before(从过去某点往前)/ since / past:距今用 ago。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp3','choice','{"stem":"\"Gloves were unknown; they had not been used ___.\"(从过去某点往前数,用哪个)","options":["then","ago","later","before"],"answer_index":3,"stem_cn":"那之前从没用过拳套。","explanation_cn":"从“过去某个时间点”往前数,用 before。✓ they had not been used before. ✗ ago(距今才用)/ then / later:过去往前用 before。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp3','choice','{"stem":"\"Mendoza had learned to box years ___ he met Humphries.\"(引导“在…之前”用哪个)","options":["since","before","until","ago"],"answer_index":1,"stem_cn":"门多萨在遇到汉弗莱斯多年前就学会了拳击。","explanation_cn":"引导“在……之前”这个时间,用 before。✓ years before he met Humphries. ✗ ago / since / until:“在…之前”用 before。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp4','choice','{"stem":"\"In those rough days, a fighter ___ get badly hurt.\"(过去“一般可能”用哪个)","options":["can","was able to","could","is able to"],"answer_index":2,"stem_cn":"在那种粗野的年代,拳手可能受重伤。","explanation_cn":"“过去的一般可能/能力(有可能受伤)”用 could。✓ a fighter could get badly hurt. ✗ was able to(表某一次成功)/ can 现在 / is able to 现在。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp4','choice','{"stem":"\"After two losses, Mendoza ___ beat Humphries in 1790.\"(某一次成功做成,不用 could)","options":["is able to","could","can","was able to"],"answer_index":3,"stem_cn":"两度落败后,门多萨在1790年终于赢了汉弗莱斯。","explanation_cn":"“某一次终于成功做成”用 was able to,不用 could。✓ was finally able to beat him in 1790. ✗ could(表一般能力)/ can / is able to:一次成功用 was able to。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp4','choice','{"stem":"\"As a boy he ___ run faster than anyone on his street.\"(过去“一般能力”用哪个)","options":["was able to","could","can","be able"],"answer_index":1,"stem_cn":"小时候他跑得比街上任何人都快。","explanation_cn":"“过去的一般能力(一向跑得快)”用 could。✓ he could run faster than anyone. ✗ was able to(一次成功)/ can / be able:一般能力用 could。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp5','choice','{"stem":"\"Mendoza was admired ___ rich and poor alike.\"(被动的发出者用哪个介词)","options":["of","with","from","by"],"answer_index":3,"stem_cn":"门多萨受到贫富一致的爱戴。","explanation_cn":"被动语态里,动作的发出者用 by 引出。✓ admired by rich and poor. ✗ with / from / of:施动者用 by。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp5','choice','{"stem":"\"The young pupil was pleased ___ so much from a champion.\"(形容词 pleased 后接不定式)","options":["learning","learn","to learn","learned"],"answer_index":2,"stem_cn":"这个年轻徒弟很高兴能从冠军那儿学到那么多。","explanation_cn":"形容词 pleased 后接“to + 动词”:pleased to learn。✓ was pleased to learn so much. ✗ learning / learn / learned:pleased 后用不定式 to learn。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp5','choice','{"stem":"\"In the end he was sorry ___ his money so carelessly.\"(形容词 sorry 后接不定式)","options":["to have spent","spending","spend","spent"],"answer_index":0,"stem_cn":"到头来他后悔把钱花得那么随意。","explanation_cn":"形容词 sorry 后接不定式;对已经做过的事表示后悔,用 to have done。✓ sorry to have spent his money. ✗ spending / spend / spent:这里用 to have spent。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp6','choice','{"stem":"\"A person who is famous and respected in their field is ___.\"(“杰出的、著名的”用哪个词)","options":["unknown","eminent","ordinary","shy"],"answer_index":1,"stem_cn":"在自己领域里很有名、受敬重的人。","explanation_cn":"在自己领域里很有名、受敬重的是 eminent(杰出的)。✓ the most eminent boxer. ✗ ordinary 普通;✗ unknown 无名;✗ shy 害羞——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp6','choice','{"stem":"\"Someone who spends money wastefully is ___.\"(“奢侈浪费的”用哪个词)","options":["extravagant","careful","thrifty","honest"],"answer_index":0,"stem_cn":"花钱大手大脚、浪费的人。","explanation_cn":"花钱大手大脚、浪费的是 extravagant(奢侈的)。✓ so extravagant that… ✗ thrifty 节俭;✗ careful 谨慎;✗ honest 诚实——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',5,'am3_l21_gp6','choice','{"stem":"\"The state of being very poor is ___.\"(“贫困”用哪个词)","options":["luxury","comfort","poverty","wealth"],"answer_index":2,"stem_cn":"非常穷的状态。","explanation_cn":"非常穷的状态是 poverty(贫困)。✓ spent his last years in poverty. ✗ wealth 财富;✗ comfort 舒适;✗ luxury 奢华——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"boxing 的意思是:","options":["摔跤","拳击","赛跑","游泳"],"answer_index":1,"explanation_cn":"boxing = 拳击。✓ boxing was very popular 拳击很流行。\n顺带记:游泳 = swimming;赛跑 = running;摔跤 = wrestling."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"prizefighter 的意思是:","options":["裁判","教练","职业拳击手","观众"],"answer_index":2,"explanation_cn":"prizefighter = 职业拳击手(旧时指赤手拳手)。✓ known as prizefighters.\n顺带记:观众 = spectator;裁判 = referee;教练 = coach."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"eminent 的意思是:","options":["年轻的","著名的,杰出的","害羞的","普通的"],"answer_index":1,"explanation_cn":"eminent = 著名的、杰出的。✓ the most eminent boxer 最杰出的拳手。\n顺带记:普通的 = ordinary;年轻的 = young;害羞的 = shy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"adore 的意思是:","options":["崇拜,爱戴","讨厌","忽视","害怕"],"answer_index":0,"explanation_cn":"adore = 崇拜、爱戴。✓ adored by rich and poor 受贫富爱戴。\n顺带记:讨厌 = hate;忽视 = ignore;害怕 = fear."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"extravagant 的意思是:","options":["节俭的","贫穷的","奢侈的,浪费的","诚实的"],"answer_index":2,"explanation_cn":"extravagant = 奢侈的、浪费的。✓ so extravagant that… 太爱挥霍以致……。\n顺带记:节俭的 = thrifty;贫穷的 = poor;诚实的 = honest."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',6,NULL,'choice','{"stem":"poverty 的意思是:","options":["名声","财富","舒适","贫困"],"answer_index":3,"explanation_cn":"poverty = 贫困。✓ in poverty 在贫困中。\n顺带记:财富 = wealth;舒适 = comfort;名声 = fame."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',7,NULL,'cloze','{"stem":"第 1 空","context":"Two hundred years ___1___, boxing had few rules. Gloves were ___2___ introduced until 1860. Daniel Mendoza ___3___ to fame as a teenager and was admired ___4___ rich and poor alike, but his extravagance later ruined him.","blank_no":1,"options":["ago","before","since","past"],"answer_index":0,"explanation_cn":"从现在往前数,用 ago。✓ Two hundred years ago, boxing had few rules."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',7,NULL,'cloze','{"stem":"第 2 空","context":"Two hundred years ___1___, boxing had few rules. Gloves were ___2___ introduced until 1860. Daniel Mendoza ___3___ to fame as a teenager and was admired ___4___ rich and poor alike, but his extravagance later ruined him.","blank_no":2,"options":["not","no","never","none"],"answer_index":0,"explanation_cn":"“直到1860年才……”用 not ... until。✓ Gloves were not introduced until 1860."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',7,NULL,'cloze','{"stem":"第 3 空","context":"Two hundred years ___1___, boxing had few rules. Gloves were ___2___ introduced until 1860. Daniel Mendoza ___3___ to fame as a teenager and was admired ___4___ rich and poor alike, but his extravagance later ruined him.","blank_no":3,"options":["rose","raised","rise","raise"],"answer_index":0,"explanation_cn":"“成名”用 rise(过去式 rose)。✓ Mendoza rose to fame as a teenager."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',7,NULL,'cloze','{"stem":"第 4 空","context":"Two hundred years ___1___, boxing had few rules. Gloves were ___2___ introduced until 1860. Daniel Mendoza ___3___ to fame as a teenager and was admired ___4___ rich and poor alike, but his extravagance later ruined him.","blank_no":4,"options":["by","with","from","of"],"answer_index":0,"explanation_cn":"被动语态的发出者用 by。✓ was admired by rich and poor alike."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',8,NULL,'choice','{"stem":"What was boxing like two hundred years ago?","options":["It was played with gloves","It was completely banned","It had almost no rules","It was only for the rich"],"answer_index":2,"explanation_cn":"课文说 there were almost no rules——两百年前的拳击几乎没有规则。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',8,NULL,'choice','{"stem":"How did Mendoza change boxing?","options":["He invented the boxing ring","He wrote its very first rules","He made it far more violent","He brought skill and ''science'' to it"],"answer_index":3,"explanation_cn":"课文说 he brought a kind of ''science'' to the ring——门多萨给拳击带来讲技巧的“科学”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',8,NULL,'choice','{"stem":"Why was Mendoza forgotten at the end of his life?","options":["He lost his money and his title","He moved to another country","He became a schoolteacher","He stopped fighting while young"],"answer_index":0,"explanation_cn":"课文说 he was so extravagant…fell into debt…after he was defeated——他挥霍破产又输了比赛,才被人遗忘。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',9,NULL,'choice','{"stem":"你想说\"直到1790年他才夺冠\"(not...until):","options":["It was not until 1790 that he won the title.","It was until not 1790 that he won the title.","It was not 1790 until that he won the title.","It was until 1790 not that he won the title."],"answer_index":0,"explanation_cn":"强调“直到…才”用 It was not until … that …。✓ It was not until 1790 that he won the title. 场合:强调某事发生得很晚。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',9,NULL,'choice','{"stem":"你想说\"门多萨十几岁就成名了\"(rise to fame):","options":["Mendoza rose to fame raised a teenager.","Mendoza raised to fame as a teenager.","Mendoza was risen to fame as a teenager.","Mendoza rose to fame as a teenager."],"answer_index":3,"explanation_cn":"“成名”用 rise(rose),后面不接一个东西。✓ Mendoza rose to fame as a teenager. 场合:说某人出名、地位上升。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',9,NULL,'choice','{"stem":"你想说\"他受到贫富一致的爱戴\"(被动 by):","options":["He was adore by rich and poor alike.","He adored by rich and poor alike.","He was adored by rich and poor alike.","He was adored with rich and poor alike."],"answer_index":2,"explanation_cn":"被动语态“被…爱戴”,发出者用 by。✓ He was adored by rich and poor alike. 场合:说某人受到大家的喜爱。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"eminent 的意思是:","options":["害羞的","著名的,杰出的","普通的","年轻的"],"answer_index":1,"explanation_cn":"eminent = 著名的、杰出的。✓ the most eminent boxer."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"poverty 的意思是:","options":["名声","舒适","财富","贫困"],"answer_index":3,"explanation_cn":"poverty = 贫困。✓ in poverty."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"\"Gloves were ___ introduced until 1860.\"(“直到…才”)","options":["none","not","no","never"],"answer_index":1,"stem_cn":"直到1860年才用上手套。","explanation_cn":"“直到…才”用 not ... until。✓ Gloves were not introduced until 1860. ✗ no / never / none:固定搭配是 not ... until。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"\"Mendoza ___ to fame as a teenager.\"(“成名”用哪个)","options":["raised","raise","rise","rose"],"answer_index":3,"stem_cn":"门多萨十几岁就成名了。","explanation_cn":"“成名”用 rise(过去式 rose),后面不接东西。✓ Mendoza rose to fame. ✗ raised(要接东西)/ rise / raise:这里用 rose。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"\"rise to fame\" 的意思是:","options":["抬高价格","举起手臂","成名,声名鹊起","早早起床"],"answer_index":2,"explanation_cn":"rise to fame = 成名、声名鹊起。✓ rose to fame very young 很年轻就成名。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"\"fall into debt\" 的意思是:","options":["摔进坑里","负债,陷入债务","生意兴隆","存下钱来"],"answer_index":1,"explanation_cn":"fall into debt = 负债、陷入债务。✓ fell into debt 债台高筑。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"Who trained Mendoza at first?","options":["Gentleman Jackson","A nobleman","Lord Byron","Richard Humphries"],"answer_index":3,"passage":"Two hundred years ago, boxing was one of the most popular sports in England, though it looked nothing like the sport we know today. Fighters used no gloves, and there were almost no rules. Gloves were not introduced until 1860, when a nobleman drew up the first proper set of regulations. One boxer, however, had already begun to turn rough fighting into a real skill long before then. His name was Daniel Mendoza, and he was born in 1764. Mendoza rose to fame very young. He was quick, clever, and light on his feet, and he brought a kind of ''science'' to the ring, teaching that brains mattered as much as strength. In his day he was enormously popular; he was admired by rich and poor alike. Richard Humphries, then the most eminent boxer in England, offered to train him, but the pupil learned so fast that the two soon became rivals. Mendoza lost to Humphries twice before he was finally able to beat him in 1790 and be crowned Champion of England. Mendoza then opened a famous academy, where even Lord Byron came to learn, and he earned huge sums for a single match. Sadly, he was so extravagant that he could never hold on to his money. Little by little he fell into debt, and after he was defeated by a younger fighter, the crowds forgot him. He spent his last years in poverty, a reminder that talent alone cannot make up for careless spending.","explanation_cn":"课文说 Richard Humphries…offered to train him——最先训练门多萨的是汉弗莱斯。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"Why did Mendoza end his life in poverty?","options":["He gave all his money away","He was too extravagant with money","He was robbed of everything","He never earned much at all"],"answer_index":1,"passage":"Two hundred years ago, boxing was one of the most popular sports in England, though it looked nothing like the sport we know today. Fighters used no gloves, and there were almost no rules. Gloves were not introduced until 1860, when a nobleman drew up the first proper set of regulations. One boxer, however, had already begun to turn rough fighting into a real skill long before then. His name was Daniel Mendoza, and he was born in 1764. Mendoza rose to fame very young. He was quick, clever, and light on his feet, and he brought a kind of ''science'' to the ring, teaching that brains mattered as much as strength. In his day he was enormously popular; he was admired by rich and poor alike. Richard Humphries, then the most eminent boxer in England, offered to train him, but the pupil learned so fast that the two soon became rivals. Mendoza lost to Humphries twice before he was finally able to beat him in 1790 and be crowned Champion of England. Mendoza then opened a famous academy, where even Lord Byron came to learn, and he earned huge sums for a single match. Sadly, he was so extravagant that he could never hold on to his money. Little by little he fell into debt, and after he was defeated by a younger fighter, the crowds forgot him. He spent his last years in poverty, a reminder that talent alone cannot make up for careless spending.","explanation_cn":"课文说 he was so extravagant that he could never hold on to his money——他太挥霍,才落得贫困。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"In what year did Mendoza become Champion of England?","options":["1836","1860","1764","1790"],"answer_index":3,"audio":"Two hundred years ago, boxing was one of the most popular sports in England, though it looked nothing like the sport we know today. Fighters used no gloves, and there were almost no rules. Gloves were not introduced until 1860, when a nobleman drew up the first proper set of regulations. One boxer, however, had already begun to turn rough fighting into a real skill long before then. His name was Daniel Mendoza, and he was born in 1764. Mendoza rose to fame very young. He was quick, clever, and light on his feet, and he brought a kind of ''science'' to the ring, teaching that brains mattered as much as strength. In his day he was enormously popular; he was admired by rich and poor alike. Richard Humphries, then the most eminent boxer in England, offered to train him, but the pupil learned so fast that the two soon became rivals. Mendoza lost to Humphries twice before he was finally able to beat him in 1790 and be crowned Champion of England. Mendoza then opened a famous academy, where even Lord Byron came to learn, and he earned huge sums for a single match. Sadly, he was so extravagant that he could never hold on to his money. Little by little he fell into debt, and after he was defeated by a younger fighter, the crowds forgot him. He spent his last years in poverty, a reminder that talent alone cannot make up for careless spending.","explanation_cn":"课文说 was finally able to beat him in 1790 and be crowned Champion——1790年他成为英格兰冠军。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l21',10,NULL,'choice','{"stem":"Who was one of Mendoza''s famous pupils?","options":["Lord Byron","The nobleman","A younger fighter","Richard Humphries"],"answer_index":0,"audio":"Two hundred years ago, boxing was one of the most popular sports in England, though it looked nothing like the sport we know today. Fighters used no gloves, and there were almost no rules. Gloves were not introduced until 1860, when a nobleman drew up the first proper set of regulations. One boxer, however, had already begun to turn rough fighting into a real skill long before then. His name was Daniel Mendoza, and he was born in 1764. Mendoza rose to fame very young. He was quick, clever, and light on his feet, and he brought a kind of ''science'' to the ring, teaching that brains mattered as much as strength. In his day he was enormously popular; he was admired by rich and poor alike. Richard Humphries, then the most eminent boxer in England, offered to train him, but the pupil learned so fast that the two soon became rivals. Mendoza lost to Humphries twice before he was finally able to beat him in 1790 and be crowned Champion of England. Mendoza then opened a famous academy, where even Lord Byron came to learn, and he earned huge sums for a single match. Sadly, he was so extravagant that he could never hold on to his money. Little by little he fell into debt, and after he was defeated by a younger fighter, the crowds forgot him. He spent his last years in poverty, a reminder that talent alone cannot make up for careless spending.","explanation_cn":"课文说 even Lord Byron came to learn——拜伦勋爵是他学校的学员之一。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l22',3,5,22,'By Heart','熟记台词','so + 形容词/副词 + that、such (a) + 名词 + that(如此…以致)、would / used to 表过去反复的动作或习惯、insist / suggest / demand that + (should) + 动词原形(虚拟)、managed to(设法做成,= could not 的反面)、present / hand sth to sb + 形容词 + 动词不定式(anxious to see)(原创承载 NCE3 L22 考点·无需净化·剧场趣事:两名演员在长演不衰的戏里都忘了台词,一张白纸让他们互相救场)','有些戏太成功了,一连上演好几年。这对演员其实挺熬人:同样的台词得一晚接一晚地重复。你会以为他们早把角色台词背得滚瓜烂熟、绝不会卡壳,可事实未必如此。一位名演员曾出演一个角色——一个在遥远城堡里被关了二十年的贵族。每到最后一幕,总有个监狱看守拿着一封信上台,把信递给这囚犯。尽管这位演员每场都要念这封信,他却坚持要求信必须完整地写出来。一天晚上,看守决定和同台的演员开个玩笑,想看看演了这么多场后,他是不是终于把信背了下来。大幕拉开,最后一幕开场,贵族独自坐在牢房的铁栏后。看守进来,把信递上——可这回却是一张白纸。看守目不转睛地盯着,急着想看会发生什么。贵族盯着白纸看了几秒,眯起眼说:“光线太暗,你念给我听吧。”说着把纸又递了回去。看守自己也一个字都想不起来,只好回道:“陛下,光线确实太暗,我得去取眼镜。”他匆匆下场,片刻后拿着真信回来,当众念给囚犯听,把全场逗得乐不可支。','{"q":"Listen and answer — Which actor read the letter aloud in the end?","options":["The jailer","The aristocrat","A third actor","No one did"],"answer_index":0}'::jsonb,'{"title":"so/such...that + would/used to + insist that (should) do","intro":"①“如此…以致…”:so + 形容词/副词 + that(so successful that…);such + (a) + 名词 + that(such a good play that…)。②would / used to 表示“过去反复发生、过去常常”:A jailer would always come on stage. / He used to rehearse before every show.③insist / suggest / demand / order that 后面的从句用 (should) + 动词原形:He insisted that it (should) be written out.④managed to = 设法做成(和 could not 相反)。⑤present / hand / give sth to sb;pleased/anxious 等形容词后接 to do。","table":{"headers":["用法","意思","例子"],"rows":[["so … that / such (a) … that","如此…以致…","so successful that it ran for years"],["would / used to","过去反复 / 过去常常","The jailer would come on stage."],["insist/suggest that + (should) do","坚持/建议…(虚拟)","insisted that it should be written out"],["managed to / present sth to sb","设法做成 / 把…递给","managed to learn it / presented it to him"]]},"specialRules":[{"rule":"so 后面直接跟形容词/副词(so good);such 后面跟名词短语(such a good play)。别写成 so a good play。","mark":"so + adj / such a + n"},{"rule":"insist / suggest / demand / order that 后面用 (should) + 动词原形,不随时态变化:demand that he arrive(不是 arrives)。","mark":"that + (should) 原形"},{"rule":"美式用词与拼写:jailer(英式 gaoler)、theater(英式 theatre)、intermission(英式 interval)。本课已按美语写。","mark":"jailer / theater"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l22',1,NULL,'Some plays are so successful that they run for years on end. In a way, this is hard on the actors, who must repeat the very same lines night after night. You would think they would know their parts by heart and never stumble. Yet that is not always so.','有些戏太成功了,一连上演好几年。这对演员其实挺熬人:同样的台词得一晚接一晚地重复。你会以为他们早把角色台词背得滚瓜烂熟、绝不会卡壳,可事实未必如此。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l22',2,NULL,'A famous actor was once cast as a nobleman who, in the story, had been locked away in a distant fortress for twenty years. In the final act, a jailer would always come onto the stage carrying a letter, which he handed to the prisoner. Even though the actor was supposed to read the letter at every performance, he always insisted that it should be written out in full.','一位名演员曾出演一个角色——一个在遥远城堡里被关了二十年的贵族。每到最后一幕,总有个监狱看守拿着一封信上台,把信递给这囚犯。尽管这位演员每场都要念这封信,他却坚持要求信必须完整地写出来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l22',3,NULL,'One night, the jailer decided to play a joke on his fellow actor. He wanted to find out whether, after so many shows, the man had finally managed to learn the letter by heart. When the curtain rose on the last act, the nobleman sat alone behind the bars of his cell.','一天晚上,看守决定和同台的演员开个玩笑,想看看演了这么多场后,他是不是终于把信背了下来。大幕拉开,最后一幕开场,贵族独自坐在牢房的铁栏后。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l22',4,NULL,'In came the jailer and presented the letter, but this time it was only a blank sheet of paper. The jailer watched eagerly, anxious to see what would happen. The nobleman stared at the blank page, then squinted and said, ''The light is dim. Read the letter to me.'' He handed the paper right back.','看守进来,把信递上——可这回却是一张白纸。看守目不转睛地盯着,急着想看会发生什么。贵族盯着白纸看了几秒,眯起眼说:“光线太暗,你念给我听吧。”说着把纸又递了回去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l22',5,NULL,'The jailer, who could not remember a single word either, replied, ''The light is indeed dim, sir. I must go get my glasses.'' He hurried off and returned a moment later with the real letter, which he read aloud to the delight of the whole theater.','看守自己也一个字都想不起来,只好回道:“陛下,光线确实太暗,我得去取眼镜。”他匆匆下场,片刻后拿着真信回来,当众念给囚犯听,把全场逗得乐不可支。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
