INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l22','by heart','',NULL,'/baɪ hɑːrt/','He knew his lines by heart.','他把台词背得滚瓜烂熟。','She learned the poem by heart.','她把这首诗背了下来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l22','play a joke on','',NULL,'/pleɪ ə dʒoʊk ɑːn/','The jailer played a joke on his colleague.','看守和同事开了个玩笑。','They played a joke on their teacher.','他们捉弄了老师一下。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l22','so ... that','',NULL,'/soʊ ... ðæt/','The play was so long that people left early.','这出戏太长了,观众提前走了。','It was so cold that the lake froze.','天冷得湖都结冰了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l22','run for years','',NULL,'/rʌn fɔːr jɪrz/','The play ran for years on end.','这出戏一连上演了好几年。','The show ran for a decade.','这台演出连演了十年。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp1','choice','{"stem":"\"The play was ___ successful that it ran for years.\"(形容词前,表“如此…以致”)","options":["very","such a","such","so"],"answer_index":3,"stem_cn":"这出戏太成功了,连演了好几年。","explanation_cn":"“如此…以致…”:so + 形容词 + that。✓ so successful that it ran for years. ✗ such(后接名词)/ such a / very:形容词前用 so。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp1','choice','{"stem":"\"It was ___ successful play that it ran for years.\"(名词短语前,表“如此…的一出…”)","options":["so a","such a","so","such"],"answer_index":1,"stem_cn":"这是一出非常成功的戏,连演了好几年。","explanation_cn":"“如此…的一出戏”:such + a + 形容词 + 名词 + that。✓ such a successful play that… ✗ so(后接形容词,不接名词短语)/ such / so a:这里用 such a。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp1','choice','{"stem":"\"The audience laughed ___ loudly that the actors stopped.\"(副词前,表“如此…以致”)","options":["so","such a","such","too"],"answer_index":0,"stem_cn":"观众笑得太响,演员都停了下来。","explanation_cn":"“如此…以致…”:so + 副词 + that。✓ laughed so loudly that… ✗ such / such a(后接名词)/ too:副词前用 so。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp2','choice','{"stem":"\"Every night the jailer ___ come onto the stage with a letter.\"(过去反复的动作:“总会”)","options":["will","is going to","would","would have"],"answer_index":2,"stem_cn":"每晚监狱看守都会拿着一封信上台。","explanation_cn":"“过去反复发生的动作(总会…)”用 would + 动词原形。✓ the jailer would come on stage. ✗ will 现在;✗ would have 完成;✗ is going to 将来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp2','choice','{"stem":"\"The old actor ___ to rehearse his lines before every show.\"(过去习惯:“过去常常”)","options":["used","uses","using","use"],"answer_index":0,"stem_cn":"这位老演员过去每场演出前都要排练台词。","explanation_cn":"“过去常常做某事(现在不这样了)”用 used to。✓ used to rehearse before every show. ✗ use / uses / using:固定说 used to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp2','choice','{"stem":"\"In those days the play ___ run for months without a break.\"(过去反复:“常会”)","options":["is","would have","would","will"],"answer_index":2,"stem_cn":"那时候这出戏常常连演几个月不停。","explanation_cn":"“过去常会…”用 would。✓ the play would run for months. ✗ will 现在;✗ would have 完成;✗ is 现在。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp3','choice','{"stem":"\"The actor insisted that the letter ___ written out in full.\"(insist that + (should) 原形)","options":["was","should be","is","will be"],"answer_index":1,"stem_cn":"那位演员坚持要求把信完整地写出来。","explanation_cn":"insist that 后面用 (should) + 动词原形;“信被写出来”是被动,用 should be written。✓ insisted that it should be written out. ✗ is / was / will be:这个虚拟结构里要用 (should) be。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp3','choice','{"stem":"\"The director suggested that everyone ___ their lines twice.\"(suggest that + (should) 原形)","options":["rehearse","rehearses","rehearsing","rehearsed"],"answer_index":0,"stem_cn":"导演建议每个人把台词排两遍。","explanation_cn":"suggest that 后面用 (should) + 动词原形,不随人称变化。✓ suggested that everyone rehearse. ✗ rehearses / rehearsed / rehearsing:这里用原形 rehearse。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp3','choice','{"stem":"\"The manager demanded that the actor ___ on time.\"(demand that + (should) 原形)","options":["arriving","arrived","arrives","arrive"],"answer_index":3,"stem_cn":"经理要求那位演员准时到。","explanation_cn":"demand that 后面用 (should) + 动词原形。✓ demanded that the actor arrive. ✗ arrives / arrived / arriving:这里用原形 arrive。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp4','choice','{"stem":"\"After many shows, had the jailer ___ to learn the letter by heart?\"(“设法学会”)","options":["managing","managed","manage","manages"],"answer_index":1,"stem_cn":"演了那么多场后,看守是否终于把信背了下来?","explanation_cn":"“设法学会”用 manage to,过去式 managed。✓ had the jailer managed to learn it? ✗ manage / managing / manages:这里用过去分词 managed(had + 过去分词)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp4','choice','{"stem":"\"Neither actor ___ to remember the lines that night.\"(“设法做到”的过去式)","options":["manages","managing","managed","manage"],"answer_index":2,"stem_cn":"那晚两个演员谁也没能记住台词。","explanation_cn":"“设法做到(那晚谁也没做到)”用 managed to。✓ Neither actor managed to remember. ✗ manage / manages / managing:一般过去用 managed。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp4','choice','{"stem":"\"''Managed to'' means about the same as ___.\"(managed to 的近义)","options":["was able to","would rather","had better","could not"],"answer_index":0,"stem_cn":"managed to 的意思接近于哪个?","explanation_cn":"managed to(设法做成)意思接近 was able to。✓ managed to = was able to. ✗ could not(相反)/ would rather / had better:意思都不同。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp5','choice','{"stem":"\"The jailer presented the letter ___ the aristocrat.\"(present sth 后接哪个介词)","options":["at","with","for","to"],"answer_index":3,"stem_cn":"看守把信递给贵族。","explanation_cn":"present sth to sb“把某物递/呈给某人”,用 to。✓ presented the letter to the aristocrat. ✗ for / at / with:present 后接 to。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp5','choice','{"stem":"\"He handed the blank sheet ___ his fellow actor.\"(hand sth 后接哪个介词)","options":["for","to","at","of"],"answer_index":1,"stem_cn":"他把那张白纸递给同台的演员。","explanation_cn":"hand sth to sb“把某物递给某人”,用 to。✓ handed the sheet to his fellow actor. ✗ for / at / of:hand 后接 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp5','choice','{"stem":"\"The jailer was anxious ___ what his colleague would do.\"(形容词 anxious 后接不定式)","options":["saw","seeing","to see","see"],"answer_index":2,"stem_cn":"看守急切地想看看同事会怎么做。","explanation_cn":"形容词 anxious 后接“to + 动词”:anxious to see。✓ anxious to see what would happen. ✗ seeing / see / saw:anxious 后用不定式 to see。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp6','choice','{"stem":"\"A member of the noble class, like a lord or duke, is an ___.\"(“贵族”用哪个词)","options":["aristocrat","engineer","actor","athlete"],"answer_index":0,"stem_cn":"像勋爵、公爵那样的贵族阶层成员。","explanation_cn":"像勋爵、公爵那样的贵族阶层成员是 aristocrat(贵族)。✓ cast as an aristocrat. ✗ athlete 运动员;✗ engineer 工程师;✗ actor 演员——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp6','choice','{"stem":"\"To look at something with your eyes partly closed is to ___.\"(“眯着眼看”用哪个词)","options":["shout","squint","swim","sneeze"],"answer_index":1,"stem_cn":"半眯着眼看东西。","explanation_cn":"半眯着眼看东西用 squint。✓ he squinted at the page. ✗ shout 喊;✗ sneeze 打喷嚏;✗ swim 游泳——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',5,'am3_l22_gp6','choice','{"stem":"\"When a light is faint and not bright, it is ___.\"(“昏暗的”用哪个词)","options":["sweet","loud","dim","heavy"],"answer_index":2,"stem_cn":"光线微弱不亮。","explanation_cn":"光线微弱不亮是 dim(昏暗的)。✓ the light is dim. ✗ loud 响;✗ sweet 甜;✗ heavy 重——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"aristocrat 的意思是:","options":["贵族","士兵","农民","商人"],"answer_index":0,"explanation_cn":"aristocrat = 贵族。✓ cast as an aristocrat 出演一个贵族。\n顺带记:农民 = farmer;士兵 = soldier;商人 = merchant."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"jailer 的意思是:","options":["画家","演员","医生","监狱看守"],"answer_index":3,"explanation_cn":"jailer = 监狱看守(美语;英式 gaoler)。✓ a jailer came on stage.\n顺带记:演员 = actor;医生 = doctor;画家 = painter."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"cell 的意思是:","options":["舞台","厨房","单人牢房","花园"],"answer_index":2,"explanation_cn":"cell = 单人牢房。✓ behind the bars of his cell 在牢房铁栏后。\n顺带记:舞台 = stage;花园 = garden;厨房 = kitchen."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"squint 的意思是:","options":["奔跑","微笑","大喊","眯着眼看"],"answer_index":3,"explanation_cn":"squint = 眯着眼看。✓ he squinted at the page 他眯眼看那张纸。\n顺带记:大喊 = shout;奔跑 = run;微笑 = smile."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"dim 的意思是:","options":["寒冷的","明亮的","昏暗的","吵闹的"],"answer_index":2,"explanation_cn":"dim = 昏暗的。✓ the light is dim 光线昏暗。\n顺带记:明亮的 = bright;吵闹的 = noisy;寒冷的 = cold."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',6,NULL,'choice','{"stem":"falter 的意思是:","options":["大笑","支吾,结巴","歌唱","鼓掌"],"answer_index":1,"explanation_cn":"falter = 支吾、结巴。✓ never falter on stage 在台上从不卡壳。\n顺带记:大笑 = laugh;歌唱 = sing;鼓掌 = applaud."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',7,NULL,'cloze','{"stem":"第 1 空","context":"The play was ___1___ successful that it ran for years. Each night a jailer ___2___ bring a letter onto the stage. One evening the jailer, curious whether the actor had ___3___ to learn the lines, handed him a blank page. The actor squinted and asked the jailer ___4___ read it aloud instead.","blank_no":1,"options":["so","such","such a","very"],"answer_index":0,"explanation_cn":"“如此…以致…”:so + 形容词 + that。✓ The play was so successful that it ran for years."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',7,NULL,'cloze','{"stem":"第 2 空","context":"The play was ___1___ successful that it ran for years. Each night a jailer ___2___ bring a letter onto the stage. One evening the jailer, curious whether the actor had ___3___ to learn the lines, handed him a blank page. The actor squinted and asked the jailer ___4___ read it aloud instead.","blank_no":2,"options":["would","will","would have","is"],"answer_index":0,"explanation_cn":"过去反复发生的动作用 would。✓ a jailer would bring a letter onto the stage."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',7,NULL,'cloze','{"stem":"第 3 空","context":"The play was ___1___ successful that it ran for years. Each night a jailer ___2___ bring a letter onto the stage. One evening the jailer, curious whether the actor had ___3___ to learn the lines, handed him a blank page. The actor squinted and asked the jailer ___4___ read it aloud instead.","blank_no":3,"options":["managed","manage","manages","managing"],"answer_index":0,"explanation_cn":"“设法学会”用 manage to,这里 had + 过去分词 managed。✓ whether the actor had managed to learn the lines."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',7,NULL,'cloze','{"stem":"第 4 空","context":"The play was ___1___ successful that it ran for years. Each night a jailer ___2___ bring a letter onto the stage. One evening the jailer, curious whether the actor had ___3___ to learn the lines, handed him a blank page. The actor squinted and asked the jailer ___4___ read it aloud instead.","blank_no":4,"options":["to","for","that","of"],"answer_index":0,"explanation_cn":"ask sb to do sth,用 to。✓ asked the jailer to read it aloud."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',8,NULL,'choice','{"stem":"Why is a long-running play hard on actors?","options":["They travel a great deal","They earn very little money","They must repeat the same lines every night","They rarely get to rehearse"],"answer_index":2,"explanation_cn":"课文说 must repeat the very same lines night after night——长演的戏要天天重复同样台词,所以熬人。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',8,NULL,'choice','{"stem":"What trick did the jailer play?","options":["He forgot to come on stage","He handed over a blank sheet of paper","He changed the ending","He hid the real letter"],"answer_index":1,"explanation_cn":"课文说 it was only a blank sheet of paper——看守把信换成了一张白纸。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',8,NULL,'choice','{"stem":"How did the aristocrat cover up that he had forgotten the lines?","options":["He said the light was dim and asked the jailer to read it","He made up brand-new lines","He walked off the stage","He simply stayed silent"],"answer_index":0,"explanation_cn":"课文说 ''The light is dim. Read the letter to me.''——贵族借口光线暗,让看守念,以掩饰自己忘词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',9,NULL,'choice','{"stem":"你想说\"这出戏太成功了,连演了好几年\"(so...that):","options":["The play was so a successful that it ran for years.","The play was so successful that it ran for years.","The play was such successful that it ran for years.","The play was successful so that it ran for years."],"answer_index":1,"explanation_cn":"“如此…以致…”:so + 形容词 + that。✓ The play was so successful that it ran for years. 场合:说明程度高到某种结果。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',9,NULL,'choice','{"stem":"你想说\"每晚看守都会拿着信上台\"(过去反复 would):","options":["Every night the jailer would come on stage with a letter.","Every night the jailer would coming on stage with a letter.","Every night the jailer would came on stage with a letter.","Every night the jailer will come on stage with a letter."],"answer_index":0,"explanation_cn":"过去反复发生的动作用 would + 动词原形。✓ Every night the jailer would come on stage with a letter. 场合:描述过去每晚都发生的事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',9,NULL,'choice','{"stem":"你想说\"他坚持要求把信完整写出来\"(insist that + should + 原形):","options":["He insisted that the letter is written out in full.","He insisted the letter writing out in full.","He insisted that the letter was written out in full.","He insisted that the letter should be written out in full."],"answer_index":3,"explanation_cn":"insist that 后面用 (should) + 动词原形;被动用 should be written。✓ He insisted that the letter should be written out in full. 场合:坚决要求某事被做到。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"aristocrat 的意思是:","options":["农民","商人","士兵","贵族"],"answer_index":3,"explanation_cn":"aristocrat = 贵族。✓ cast as an aristocrat."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"dim 的意思是:","options":["昏暗的","明亮的","寒冷的","吵闹的"],"answer_index":0,"explanation_cn":"dim = 昏暗的。✓ the light is dim."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"\"The play was ___ successful that it ran for years.\"(形容词前,表“如此…以致”)","options":["very","such","such a","so"],"answer_index":3,"stem_cn":"这出戏太成功了,连演了好几年。","explanation_cn":"“如此…以致…”:so + 形容词 + that。✓ so successful that it ran for years. ✗ such / such a(后接名词)/ very:形容词前用 so。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"\"Every night the jailer ___ bring a letter on stage.\"(过去反复的动作)","options":["would","is","will","would have"],"answer_index":0,"stem_cn":"每晚看守都会拿封信上台。","explanation_cn":"过去反复发生的动作用 would。✓ the jailer would bring a letter on stage. ✗ will 现在;✗ would have 完成;✗ is 现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"\"by heart\" 的意思是:","options":["真心地","从头开始","用力地","凭记忆,熟记于心"],"answer_index":3,"explanation_cn":"by heart = 凭记忆、熟记于心。✓ know his lines by heart 把台词背得滚瓜烂熟。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"\"play a joke on\" 的意思是:","options":["教某人做游戏","对某人认真","捉弄某人,开某人玩笑","和某人玩游戏"],"answer_index":2,"explanation_cn":"play a joke on = 捉弄某人、开某人玩笑。✓ played a joke on his colleague 捉弄了同事。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"What role was the famous actor playing?","options":["A nobleman imprisoned for twenty years","A jailer","A king","A soldier"],"answer_index":0,"passage":"Some plays are so successful that they run for years on end. In a way, this is hard on the actors, who must repeat the very same lines night after night. You would think they would know their parts by heart and never stumble. Yet that is not always so. A famous actor was once cast as a nobleman who, in the story, had been locked away in a distant fortress for twenty years. In the final act, a jailer would always come onto the stage carrying a letter, which he handed to the prisoner. Even though the actor was supposed to read the letter at every performance, he always insisted that it should be written out in full. One night, the jailer decided to play a joke on his fellow actor. He wanted to find out whether, after so many shows, the man had finally managed to learn the letter by heart. When the curtain rose on the last act, the nobleman sat alone behind the bars of his cell. In came the jailer and presented the letter, but this time it was only a blank sheet of paper. The jailer watched eagerly, anxious to see what would happen. The nobleman stared at the blank page, then squinted and said, ''The light is dim. Read the letter to me.'' He handed the paper right back. The jailer, who could not remember a single word either, replied, ''The light is indeed dim, sir. I must go get my glasses.'' He hurried off and returned a moment later with the real letter, which he read aloud to the delight of the whole theater.","explanation_cn":"课文说 cast as a nobleman who…had been locked away…for twenty years——他演一个被关了二十年的贵族。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"What was on the paper the jailer handed over that night?","options":["The wrong lines","A secret message","Nothing — it was blank","The ending of the play"],"answer_index":2,"passage":"Some plays are so successful that they run for years on end. In a way, this is hard on the actors, who must repeat the very same lines night after night. You would think they would know their parts by heart and never stumble. Yet that is not always so. A famous actor was once cast as a nobleman who, in the story, had been locked away in a distant fortress for twenty years. In the final act, a jailer would always come onto the stage carrying a letter, which he handed to the prisoner. Even though the actor was supposed to read the letter at every performance, he always insisted that it should be written out in full. One night, the jailer decided to play a joke on his fellow actor. He wanted to find out whether, after so many shows, the man had finally managed to learn the letter by heart. When the curtain rose on the last act, the nobleman sat alone behind the bars of his cell. In came the jailer and presented the letter, but this time it was only a blank sheet of paper. The jailer watched eagerly, anxious to see what would happen. The nobleman stared at the blank page, then squinted and said, ''The light is dim. Read the letter to me.'' He handed the paper right back. The jailer, who could not remember a single word either, replied, ''The light is indeed dim, sir. I must go get my glasses.'' He hurried off and returned a moment later with the real letter, which he read aloud to the delight of the whole theater.","explanation_cn":"课文说 it was only a blank sheet of paper——那晚递上的纸是空白的。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"What did the jailer go to fetch?","options":["Another actor","His glasses and the real letter","A lamp","A new script"],"answer_index":1,"audio":"Some plays are so successful that they run for years on end. In a way, this is hard on the actors, who must repeat the very same lines night after night. You would think they would know their parts by heart and never stumble. Yet that is not always so. A famous actor was once cast as a nobleman who, in the story, had been locked away in a distant fortress for twenty years. In the final act, a jailer would always come onto the stage carrying a letter, which he handed to the prisoner. Even though the actor was supposed to read the letter at every performance, he always insisted that it should be written out in full. One night, the jailer decided to play a joke on his fellow actor. He wanted to find out whether, after so many shows, the man had finally managed to learn the letter by heart. When the curtain rose on the last act, the nobleman sat alone behind the bars of his cell. In came the jailer and presented the letter, but this time it was only a blank sheet of paper. The jailer watched eagerly, anxious to see what would happen. The nobleman stared at the blank page, then squinted and said, ''The light is dim. Read the letter to me.'' He handed the paper right back. The jailer, who could not remember a single word either, replied, ''The light is indeed dim, sir. I must go get my glasses.'' He hurried off and returned a moment later with the real letter, which he read aloud to the delight of the whole theater.","explanation_cn":"课文说 returned…with the real letter…''I must go get my glasses.''——看守去取了眼镜和真信。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l22',10,NULL,'choice','{"stem":"How did the whole theater react in the end?","options":["They were delighted","They fell asleep","They left early","They booed loudly"],"answer_index":0,"audio":"Some plays are so successful that they run for years on end. In a way, this is hard on the actors, who must repeat the very same lines night after night. You would think they would know their parts by heart and never stumble. Yet that is not always so. A famous actor was once cast as a nobleman who, in the story, had been locked away in a distant fortress for twenty years. In the final act, a jailer would always come onto the stage carrying a letter, which he handed to the prisoner. Even though the actor was supposed to read the letter at every performance, he always insisted that it should be written out in full. One night, the jailer decided to play a joke on his fellow actor. He wanted to find out whether, after so many shows, the man had finally managed to learn the letter by heart. When the curtain rose on the last act, the nobleman sat alone behind the bars of his cell. In came the jailer and presented the letter, but this time it was only a blank sheet of paper. The jailer watched eagerly, anxious to see what would happen. The nobleman stared at the blank page, then squinted and said, ''The light is dim. Read the letter to me.'' He handed the paper right back. The jailer, who could not remember a single word either, replied, ''The light is indeed dim, sir. I must go get my glasses.'' He hurried off and returned a moment later with the real letter, which he read aloud to the delight of the whole theater.","explanation_cn":"课文说 to the delight of the whole theater——全场观众乐不可支。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l23',3,5,23,'One Man''s Meat Is Another Man''s Poison','各有所爱','条件句(if + 过去时 → 主句 would do,与现在相反;if + 过去完成 → would have done,与过去相反)、since / for / ago 表时间、most(大多数)/ the most(最…)/ most of、as 的多义(因为 / 当…时 / 像…一样)、现在完成进行时 has been doing、happen to(碰巧)(原创承载 NCE3 L23 考点·无需净化·谈饮食偏好因文化而异 + 收集的花园蜗牛在朋友家逃得满走廊都是的趣事)','在决定什么能吃、什么不能吃这件事上,人往往很不讲逻辑。比如你若在地中海一带长大,就会把章鱼当成美味,还理解不了别人为什么觉得它恶心;可反过来,一想到用动物油炸土豆,你的胃就要翻腾——尽管在世界许多地方,这早就是再普通不过的做法。朴素的事实是:我们大多数人从小被养成吃某些食物,便一辈子只认这些。世上没有哪种生物比普通的花园蜗牛招来更多褒贬了。用葡萄酒煮过,蜗牛在某些国家是难得的珍馐,也有人从很小起就把它当成食物。我的朋友罗伯特,自我认识他起就爱吃蜗牛。因为他住在大城市的公寓里,没有自家花园,多年来他一直央我从我的花园里替他捉蜗牛。有一天,一场大雨后,我碰巧正在外面散步,忽然看见几十只蜗牛正爬过我心爱的花草。一时冲动,我捉了好几打,装进纸袋,开车送去给罗伯特。他高兴极了。我把袋子放在门厅,两人聊了两个钟头。我早把蜗牛忘得一干二净,直到罗伯特非留我吃晚饭——主菜当然是蜗牛。等我们走回门厅,都愣住了:蜗牛全跑了出来,把整条走廊占得满满当当!打那以后,我再也没法用从前的眼光看蜗牛了。','{"q":"Listen and answer — What made the writer collect snails for his friend that particular day?","options":["A heavy shower brought many snails onto his plants","Robert paid him to do it","It was Robert''s birthday","He wanted to eat them himself"],"answer_index":0}'::jsonb,'{"title":"条件句 / since-for-ago / most / as 多义 / 现在完成进行","intro":"①条件句:与现在相反,if + 过去时,主句 would do(If I lived here, I would…);与过去相反,if + 过去完成,主句 would have done。②for + 一段时间(for years);since + 起点(since childhood);ago 从现在往前数(three days ago)。③most = 大多数(most people / most of us);the most = 最…(the most delicious)。④as 有多义:because(因为)、when(当…时)、like(像…一样,as ... as)。⑤现在完成进行 has/have been doing 表示“一直做到现在”;happen to do 表示“碰巧”。","table":{"headers":["用法","意思","例子"],"rows":[["if + 过去时, would do","与现在相反的假设","If I lived here, I would love it."],["for / since / ago","一段时间 / 起点 / 距今","for years / since childhood / days ago"],["most / the most","大多数 / 最…","most of us / the most delicious"],["as = because/when/like","因为/当…时/像","As he lives here… / as I walked…"]]},"specialRules":[{"rule":"for 后接“一段时间”,since 后接“起点”:for three years / since 2010。别混。","mark":"for / since"},{"rule":"most 直接跟名词表“大多数”(most people);表“我们中的大多数”用 most of us;the most 才是最高级“最…”。","mark":"most / most of / the most"},{"rule":"美式食物用词:french fries(英式 chips)、eggplant(英式 aubergine)、cookie(英式 biscuit)。本课已按美语写。","mark":"french fries / eggplant"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l23',1,NULL,'People become quite illogical when they try to decide what may be eaten and what may not. If you grew up along the Mediterranean, for example, you would think of octopus as a great delicacy, and you would not be able to understand why others find it repulsive.','在决定什么能吃、什么不能吃这件事上,人往往很不讲逻辑。比如你若在地中海一带长大,就会把章鱼当成美味,还理解不了别人为什么觉得它恶心。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l23',2,NULL,'On the other hand, your stomach might turn at the thought of frying potatoes in animal fat, though that has long been an ordinary practice in many parts of the world. The plain truth is that most of us are raised to eat certain foods, and we stick to them for the rest of our lives.','可反过来,一想到用动物油炸土豆,你的胃就要翻腾——尽管在世界许多地方,这早就是再普通不过的做法。朴素的事实是:我们大多数人从小被养成吃某些食物,便一辈子只认这些。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l23',3,NULL,'No creature has drawn more praise and more abuse than the ordinary garden snail. Cooked in wine, snails are a great luxury in some countries, and there are people who, ever since their earliest years, have learned to think of them as food. My friend Robert has loved snails for as long as I have known him.','世上没有哪种生物比普通的花园蜗牛招来更多褒贬了。用葡萄酒煮过,蜗牛在某些国家是难得的珍馐,也有人从很小起就把它当成食物。我的朋友罗伯特,自我认识他起就爱吃蜗牛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l23',4,NULL,'As he lives in an apartment in a big city, he has no garden of his own, and for years he has been asking me to gather snails from mine. One day, after a heavy shower, I happened to be walking outside when I noticed dozens of snails crawling over my prize plants. On a sudden impulse, I collected several dozen, dropped them into a paper bag, and drove them over to Robert.','因为他住在大城市的公寓里,没有自家花园,多年来他一直央我从我的花园里替他捉蜗牛。有一天,一场大雨后,我碰巧正在外面散步,忽然看见几十只蜗牛正爬过我心爱的花草。一时冲动,我捉了好几打,装进纸袋,开车送去给罗伯特。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l23',5,NULL,'He was delighted. I set the bag down in the hall, and we chatted for a couple of hours. I had completely forgotten the snails until Robert insisted I stay for dinner, snails, of course, being the main dish. When we walked back to the hall, we froze: the snails had escaped and taken over the entire hallway. I have never been able to look at a snail the same way since.','他高兴极了。我把袋子放在门厅,两人聊了两个钟头。我早把蜗牛忘得一干二净,直到罗伯特非留我吃晚饭——主菜当然是蜗牛。等我们走回门厅,都愣住了:蜗牛全跑了出来,把整条走廊占得满满当当!打那以后,我再也没法用从前的眼光看蜗牛了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','illogical','/ɪˈlɑːdʒɪkl/','adj','不合逻辑的','people become quite illogical') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','delicacy','/ˈdelɪkəsi/','n','美味,佳肴','a great delicacy') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','repulsive','/rɪˈpʌlsɪv/','adj','令人厌恶的','find it repulsive') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','despise','/dɪˈspaɪz/','v','鄙视,看不起','snails are despised') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','luxury','/ˈlʌkʃəri/','n','奢侈品,珍品','a great luxury') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am3_l23','associate','/əˈsoʊʃieɪt/','v','联想到,把…联系起来','associate snails with food') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
