INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l23','apartment','flat','公寓;美语 apartment,英式 flat') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l23','eggplant','aubergine','茄子;美语 eggplant,英式 aubergine') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
