INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l23','one man''s meat is another man''s poison','',NULL,'/wʌn mænz miːt/','Snails? One man''s meat is another man''s poison.','蜗牛?各人口味不同,萝卜青菜各有所爱。','He loves jazz, she hates it — one man''s meat is another man''s poison.','他爱爵士乐,她讨厌——各有所爱罢了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l23','stick to','',NULL,'/stɪk tə/','We stick to the foods we grew up with.','我们只认从小吃惯的食物。','Let''s stick to the plan.','我们就按原计划来吧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l23','on a sudden impulse','',NULL,'/ɑːn ə ˈsʌdn ˈɪmpʌls/','On a sudden impulse, I collected the snails.','一时冲动,我把蜗牛收集了起来。','On a sudden impulse, she bought a ticket.','一时冲动,她买了张票。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l23','take possession of','',NULL,'/teɪk pəˈzeʃn əv/','The snails took possession of the hall.','蜗牛占领了整个门厅。','The new owners took possession of the house.','新主人接管了这座房子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp1','choice','{"stem":"\"If you grew up by the sea, you ___ eat octopus happily.\"(与现在相反的虚拟:if 从句用过去时,主句用哪种形式)","options":["would","are going to","would have","will"],"answer_index":0,"stem_cn":"你要是在海边长大,就会乐意吃章鱼。","explanation_cn":"与现在事实相反的虚拟:if 从句用过去时,主句用 would + 动词原形。✓ If you grew up by the sea, you would eat octopus. ✗ will(真实条件)/ would have(与过去相反)/ are going to:这里主句用 would。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp1','choice','{"stem":"\"If I ___ in the Mediterranean, I would love octopus.\"(与现在相反:if 从句用什么时态)","options":["will live","lived","had lived","live"],"answer_index":1,"stem_cn":"我要是住在地中海一带,就会爱吃章鱼。","explanation_cn":"与现在事实相反的虚拟,if 从句用过去时。✓ If I lived in the Mediterranean… ✗ live(真实条件)/ had lived(与过去相反)/ will live:这里用过去时 lived。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp1','choice','{"stem":"\"If you had grown up there, you ___ octopus a treat.\"(与过去事实相反的虚拟)","options":["would have considered","considered","will consider","would consider"],"answer_index":0,"stem_cn":"你要是在那儿长大,当年就会把章鱼当美味。","explanation_cn":"与过去事实相反的虚拟,主句用 would have + 过去分词。✓ If you had grown up there, you would have considered… ✗ would consider / considered / will consider:与过去相反要用 would have considered。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp2','choice','{"stem":"\"Robert has loved snails ___ many years.\"(表“一段时间”用哪个)","options":["from","since","ago","for"],"answer_index":3,"stem_cn":"罗伯特爱吃蜗牛很多年了。","explanation_cn":"表示“持续了一段时间”用 for + 时间段。✓ for many years. ✗ since(接起点)/ ago(距今)/ from:一段时间用 for。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp2','choice','{"stem":"\"He has enjoyed snails ___ his earliest years.\"(表“从某时起”用哪个)","options":["since","until","ago","for"],"answer_index":0,"stem_cn":"他从很小的时候起就爱吃蜗牛。","explanation_cn":"表示“从某个时间点起”用 since + 起点。✓ since his earliest years. ✗ for(接时间段)/ ago / until:起点用 since。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp2','choice','{"stem":"\"I collected those snails a few days ___.\"(距今往前数用哪个)","options":["before","for","since","ago"],"answer_index":3,"stem_cn":"那些蜗牛是我几天前收集的。","explanation_cn":"从“现在”往前数多久用 ago。✓ a few days ago. ✗ since / for / before:距今用 ago。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp3','choice','{"stem":"\"___ of us are raised to eat certain foods.\"(表“我们中的大多数”)","options":["Almost","Most","Much","The most"],"answer_index":1,"stem_cn":"我们大多数人从小被养成吃某些食物。","explanation_cn":"“我们中的大多数”用 most of us。✓ Most of us are raised… ✗ The most(最高级)/ Almost(几乎,副词)/ Much(修饰不可数):这里用 Most。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp3','choice','{"stem":"\"This is ___ delicious dish on the whole menu.\"(最高级“最…”)","options":["most","a most","more","the most"],"answer_index":3,"stem_cn":"这是整张菜单上最好吃的一道菜。","explanation_cn":"最高级“最…”用 the most + 形容词。✓ the most delicious dish. ✗ most(大多数)/ more(更)/ a most:最高级要用 the most。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp3','choice','{"stem":"\"___ people enjoy some foods that others dislike.\"(表“大多数人”,后接名词)","options":["Much","Most","The most","Almost"],"answer_index":1,"stem_cn":"大多数人都爱吃一些别人不喜欢的食物。","explanation_cn":"“大多数人”直接用 most + 名词。✓ Most people enjoy… ✗ The most / Almost / Much:表“大多数”用 most。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp4','choice','{"stem":"\"___ he lives in an apartment, Robert has no garden.\"(表“因为、由于”的连词)","options":["As","While","Although","Unless"],"answer_index":0,"stem_cn":"因为住公寓,罗伯特没有自己的花园。","explanation_cn":"表示“因为、由于”的连词用 as。✓ As he lives in an apartment… ✗ While(当…时/尽管)/ Unless(除非)/ Although(虽然):这里 as 表原因。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp4','choice','{"stem":"\"I noticed the snails ___ I was walking in the garden.\"(表“当…的时候”的连词)","options":["because","so","as","if"],"answer_index":2,"stem_cn":"我在花园里走的时候注意到了那些蜗牛。","explanation_cn":"表示“当…的时候”的连词用 as。✓ as I was walking in the garden. ✗ because(因为)/ so(所以)/ if(如果):这里 as 表时间。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp4','choice','{"stem":"\"Cooked well, snails can be ___ tasty as fish.\"(“与…一样…”的比较结构,填相同的那个词)","options":["very","as","so","too"],"answer_index":1,"stem_cn":"做得好的话,蜗牛能像鱼一样美味。","explanation_cn":"“与…一样…”的比较用 as + 形容词 + as。✓ as tasty as fish. ✗ so / too / very:比较结构第一个空用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp5','choice','{"stem":"\"For years Robert ___ me to collect snails.\"(现在完成进行:一直在做)","options":["asked","is asking","asks","has been asking"],"answer_index":3,"stem_cn":"多年来罗伯特一直让我收集蜗牛。","explanation_cn":"“过去一直持续到现在的动作”用现在完成进行 has been doing。✓ Robert has been asking me for years. ✗ asks / asked / is asking:持续到现在用 has been asking。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp5','choice','{"stem":"\"I ___ to be walking outside when I saw them.\"(“碰巧正在做某事”,过去)","options":["happened","happening","happens","happen"],"answer_index":0,"stem_cn":"我碰巧正在外面走,就看见了它们。","explanation_cn":"“碰巧正在做某事”用 happen to be doing,过去用 happened。✓ I happened to be walking outside. ✗ happen / happens / happening:这里用过去式 happened。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp5','choice','{"stem":"\"She ___ studying French for three years now.\"(现在完成进行时:一直…到现在)","options":["has","had been","has been","is"],"answer_index":2,"stem_cn":"到现在她已经学了三年法语了。","explanation_cn":"“到现在一直……”用现在完成进行 has been doing。✓ She has been studying French for three years. ✗ has / is / had been:强调持续到现在用 has been。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp6','choice','{"stem":"\"A rare and delicious food is a ___.\"(“美味佳肴”用哪个词)","options":["delicacy","medicine","tool","poison"],"answer_index":0,"stem_cn":"稀有又好吃的食物。","explanation_cn":"稀有又好吃的食物是 delicacy(美味佳肴)。✓ a great delicacy. ✗ poison 毒药;✗ medicine 药;✗ tool 工具——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp6','choice','{"stem":"\"Something so unpleasant it makes you feel sick is ___.\"(“令人厌恶的”用哪个词)","options":["gentle","delicious","cheap","repulsive"],"answer_index":3,"stem_cn":"难闻难看到让人反胃的。","explanation_cn":"难闻难看到让人反胃的是 repulsive(令人厌恶的)。✓ find it repulsive. ✗ delicious 美味;✗ gentle 温和;✗ cheap 便宜——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',5,'am3_l23_gp6','choice','{"stem":"\"To look down on something with strong dislike is to ___ it.\"(“鄙视”用哪个词)","options":["collect","admire","despise","enjoy"],"answer_index":2,"stem_cn":"强烈厌恶、瞧不起某物。","explanation_cn":"强烈厌恶、瞧不起某物用 despise(鄙视)。✓ snails are despised. ✗ admire 崇拜;✗ enjoy 享受;✗ collect 收集——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"illogical 的意思是:","options":["合理的","不合逻辑的","勇敢的","礼貌的"],"answer_index":1,"explanation_cn":"illogical = 不合逻辑的。✓ people become quite illogical 人变得很不讲逻辑。\n顺带记:合理的 = reasonable;礼貌的 = polite;勇敢的 = brave."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"delicacy 的意思是:","options":["家具","毒药","美味,佳肴","工具"],"answer_index":2,"explanation_cn":"delicacy = 美味、佳肴。✓ a great delicacy 一道美味。\n顺带记:毒药 = poison;工具 = tool;家具 = furniture."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"repulsive 的意思是:","options":["令人厌恶的","温暖的","迷人的","便宜的"],"answer_index":0,"explanation_cn":"repulsive = 令人厌恶的。✓ find it repulsive 觉得它恶心。\n顺带记:迷人的 = charming;温暖的 = warm;便宜的 = cheap."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"despise 的意思是:","options":["收集","崇拜","鄙视","购买"],"answer_index":2,"explanation_cn":"despise = 鄙视、看不起。✓ snails are despised 蜗牛被人嫌弃。\n顺带记:崇拜 = admire;购买 = buy;收集 = collect."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"luxury 的意思是:","options":["奢侈品,珍品","垃圾","必需品","工具"],"answer_index":0,"explanation_cn":"luxury = 奢侈品、珍品。✓ a great luxury 难得的珍馐。\n顺带记:必需品 = necessity;垃圾 = garbage;工具 = tool."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',6,NULL,'choice','{"stem":"impulse 的意思是:","options":["计划","规则","习惯","冲动"],"answer_index":3,"explanation_cn":"impulse = 冲动。✓ on a sudden impulse 一时冲动。\n顺带记:计划 = plan;习惯 = habit;规则 = rule."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',7,NULL,'cloze','{"stem":"第 1 空","context":"People are quite illogical about food. If you grew up by the Mediterranean, you ___1___ love octopus. My friend Robert has loved snails ___2___ he was a child. ___3___ he lives in an apartment, he asked me to collect snails from my garden. One day I ___4___ to notice dozens of them after a heavy shower.","blank_no":1,"options":["would","will","would have","are"],"answer_index":0,"explanation_cn":"与现在相反的虚拟,主句用 would + 动词原形。✓ If you grew up by the Mediterranean, you would love octopus."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',7,NULL,'cloze','{"stem":"第 2 空","context":"People are quite illogical about food. If you grew up by the Mediterranean, you ___1___ love octopus. My friend Robert has loved snails ___2___ he was a child. ___3___ he lives in an apartment, he asked me to collect snails from my garden. One day I ___4___ to notice dozens of them after a heavy shower.","blank_no":2,"options":["since","for","ago","until"],"answer_index":0,"explanation_cn":"表示“从…起”用 since + 起点。✓ has loved snails since he was a child."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',7,NULL,'cloze','{"stem":"第 3 空","context":"People are quite illogical about food. If you grew up by the Mediterranean, you ___1___ love octopus. My friend Robert has loved snails ___2___ he was a child. ___3___ he lives in an apartment, he asked me to collect snails from my garden. One day I ___4___ to notice dozens of them after a heavy shower.","blank_no":3,"options":["As","Unless","Although","While"],"answer_index":0,"explanation_cn":"表示“因为、由于”的连词用 as。✓ As he lives in an apartment, he asked me to collect snails."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',7,NULL,'cloze','{"stem":"第 4 空","context":"People are quite illogical about food. If you grew up by the Mediterranean, you ___1___ love octopus. My friend Robert has loved snails ___2___ he was a child. ___3___ he lives in an apartment, he asked me to collect snails from my garden. One day I ___4___ to notice dozens of them after a heavy shower.","blank_no":4,"options":["happened","happen","happens","happening"],"answer_index":0,"explanation_cn":"“碰巧……”用 happen to,过去用 happened。✓ One day I happened to notice dozens of them."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',8,NULL,'choice','{"stem":"According to the writer, why do people eat the foods they eat?","options":["They are always the cheapest","Doctors chose them","They were raised on them","They read about them in books"],"answer_index":2,"explanation_cn":"课文说 most of us are raised to eat certain foods——大多数人从小被养成吃某些食物。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',8,NULL,'choice','{"stem":"Why can''t Robert keep snails himself?","options":["He has no money","He dislikes snails","Snails are illegal there","He lives in an apartment with no garden"],"answer_index":3,"explanation_cn":"课文说 As he lives in an apartment…he has no garden of his own——罗伯特住公寓,没花园,只好托人捉。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',8,NULL,'choice','{"stem":"What happened to the snails at Robert''s place?","options":["They escaped and took over the hall","They died in the bag","They were given away","They were cooked at once"],"answer_index":0,"explanation_cn":"课文说 the snails had escaped and taken over the entire hallway——蜗牛跑出来占满了走廊。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',9,NULL,'choice','{"stem":"你想说\"我要是住在地中海一带,就会爱吃章鱼\"(与现在相反的虚拟):","options":["If I live in the Mediterranean, I would love octopus.","If I lived in the Mediterranean, I would love octopus.","If I had lived in the Mediterranean, I would love octopus.","If I lived in the Mediterranean, I will love octopus."],"answer_index":1,"explanation_cn":"与现在事实相反的虚拟:if + 过去时,主句 would + 原形。✓ If I lived in the Mediterranean, I would love octopus. 场合:对与现在不符的情况作假设。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',9,NULL,'choice','{"stem":"你想说\"多年来他一直让我收集蜗牛\"(现在完成进行):","options":["For years he asking me to collect snails.","For years he has asked me to collect snails ago.","For years he is asking me to collect snails.","For years he has been asking me to collect snails."],"answer_index":3,"explanation_cn":"“过去一直持续到现在”用现在完成进行 has been asking。✓ For years he has been asking me to collect snails. 场合:强调某动作一直持续到现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',9,NULL,'choice','{"stem":"你想说\"因为住公寓,他没有花园\"(用表“因为”的连词开头):","options":["As he lives in an apartment, so he has no garden.","As he lives in an apartment, but he has no garden.","As he lives in an apartment, he has no garden.","As does he live in an apartment, he has no garden."],"answer_index":2,"explanation_cn":"as 引导原因“因为”;这一句用 as 开头,后面不再加 but/so。✓ As he lives in an apartment, he has no garden. 场合:说明原因。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"delicacy 的意思是:","options":["毒药","美味,佳肴","家具","工具"],"answer_index":1,"explanation_cn":"delicacy = 美味、佳肴。✓ a great delicacy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"repulsive 的意思是:","options":["便宜的","温暖的","迷人的","令人厌恶的"],"answer_index":3,"explanation_cn":"repulsive = 令人厌恶的。✓ find it repulsive."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"\"If I ___ in the Mediterranean, I would love octopus.\"(与现在相反,if 从句用什么时态)","options":["had lived","lived","will live","live"],"answer_index":1,"stem_cn":"我要是住在地中海一带,就会爱吃章鱼。","explanation_cn":"与现在相反的虚拟,if 从句用过去时。✓ If I lived in the Mediterranean… ✗ live(真实条件)/ had lived(与过去相反)/ will live:这里用过去时 lived。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"\"Robert has loved snails ___ many years.\"(表一段时间用哪个)","options":["since","ago","from","for"],"answer_index":3,"stem_cn":"罗伯特爱吃蜗牛很多年了。","explanation_cn":"表“持续一段时间”用 for。✓ has loved snails for many years. ✗ since(起点)/ ago(距今)/ from:一段时间用 for。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"\"one man''s meat is another man''s poison\" 的意思是:","options":["各有所爱,萝卜青菜各有所爱","有毒的食物不能吃","吃肉会中毒","大家口味都一样"],"answer_index":0,"explanation_cn":"one man''s meat is another man''s poison = 各人口味不同、各有所爱。✓ 甲之美味,乙之毒药。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"\"on a sudden impulse\" 的意思是:","options":["出于习惯","按计划地","一时冲动之下","经过深思熟虑"],"answer_index":2,"explanation_cn":"on a sudden impulse = 一时冲动之下。✓ On a sudden impulse, I collected them 一时冲动我就收集了它们。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"How does the writer feel about eating snails himself?","options":["He eats them daily","He does not fancy the idea","He sells them","He loves them"],"answer_index":1,"passage":"People become quite illogical when they try to decide what may be eaten and what may not. If you grew up along the Mediterranean, for example, you would think of octopus as a great delicacy, and you would not be able to understand why others find it repulsive. On the other hand, your stomach might turn at the thought of frying potatoes in animal fat, though that has long been an ordinary practice in many parts of the world. The plain truth is that most of us are raised to eat certain foods, and we stick to them for the rest of our lives. No creature has drawn more praise and more abuse than the ordinary garden snail. Cooked in wine, snails are a great luxury in some countries, and there are people who, ever since their earliest years, have learned to think of them as food. My friend Robert has loved snails for as long as I have known him. As he lives in an apartment in a big city, he has no garden of his own, and for years he has been asking me to gather snails from mine. One day, after a heavy shower, I happened to be walking outside when I noticed dozens of snails crawling over my prize plants. On a sudden impulse, I collected several dozen, dropped them into a paper bag, and drove them over to Robert. He was delighted. I set the bag down in the hall, and we chatted for a couple of hours. I had completely forgotten the snails until Robert insisted I stay for dinner, snails, of course, being the main dish. When we walked back to the hall, we froze: the snails had escaped and taken over the entire hallway. I have never been able to look at a snail the same way since.","explanation_cn":"课文说 I did not fancy the idea——作者自己并不想吃蜗牛。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"What is the main point of the first paragraph?","options":["Frying food is unhealthy","Octopus is the best food","Snails are dangerous","Food likes and dislikes are learned, not logical"],"answer_index":3,"passage":"People become quite illogical when they try to decide what may be eaten and what may not. If you grew up along the Mediterranean, for example, you would think of octopus as a great delicacy, and you would not be able to understand why others find it repulsive. On the other hand, your stomach might turn at the thought of frying potatoes in animal fat, though that has long been an ordinary practice in many parts of the world. The plain truth is that most of us are raised to eat certain foods, and we stick to them for the rest of our lives. No creature has drawn more praise and more abuse than the ordinary garden snail. Cooked in wine, snails are a great luxury in some countries, and there are people who, ever since their earliest years, have learned to think of them as food. My friend Robert has loved snails for as long as I have known him. As he lives in an apartment in a big city, he has no garden of his own, and for years he has been asking me to gather snails from mine. One day, after a heavy shower, I happened to be walking outside when I noticed dozens of snails crawling over my prize plants. On a sudden impulse, I collected several dozen, dropped them into a paper bag, and drove them over to Robert. He was delighted. I set the bag down in the hall, and we chatted for a couple of hours. I had completely forgotten the snails until Robert insisted I stay for dinner, snails, of course, being the main dish. When we walked back to the hall, we froze: the snails had escaped and taken over the entire hallway. I have never been able to look at a snail the same way since.","explanation_cn":"课文第一段说 most of us are raised to eat certain foods——饮食好恶是从小养成的,并不讲逻辑。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"What was Robert going to serve for dinner?","options":["Fish","Snails","Fried potatoes","Octopus"],"answer_index":1,"audio":"People become quite illogical when they try to decide what may be eaten and what may not. If you grew up along the Mediterranean, for example, you would think of octopus as a great delicacy, and you would not be able to understand why others find it repulsive. On the other hand, your stomach might turn at the thought of frying potatoes in animal fat, though that has long been an ordinary practice in many parts of the world. The plain truth is that most of us are raised to eat certain foods, and we stick to them for the rest of our lives. No creature has drawn more praise and more abuse than the ordinary garden snail. Cooked in wine, snails are a great luxury in some countries, and there are people who, ever since their earliest years, have learned to think of them as food. My friend Robert has loved snails for as long as I have known him. As he lives in an apartment in a big city, he has no garden of his own, and for years he has been asking me to gather snails from mine. One day, after a heavy shower, I happened to be walking outside when I noticed dozens of snails crawling over my prize plants. On a sudden impulse, I collected several dozen, dropped them into a paper bag, and drove them over to Robert. He was delighted. I set the bag down in the hall, and we chatted for a couple of hours. I had completely forgotten the snails until Robert insisted I stay for dinner, snails, of course, being the main dish. When we walked back to the hall, we froze: the snails had escaped and taken over the entire hallway. I have never been able to look at a snail the same way since.","explanation_cn":"课文说 Snails, of course, would be the main dish——罗伯特请客的主菜是蜗牛。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l23',10,NULL,'choice','{"stem":"How did the writer react when he saw the escaped snails?","options":["He was dismayed","He caught them all at once","He fainted","He laughed happily"],"answer_index":0,"audio":"People become quite illogical when they try to decide what may be eaten and what may not. If you grew up along the Mediterranean, for example, you would think of octopus as a great delicacy, and you would not be able to understand why others find it repulsive. On the other hand, your stomach might turn at the thought of frying potatoes in animal fat, though that has long been an ordinary practice in many parts of the world. The plain truth is that most of us are raised to eat certain foods, and we stick to them for the rest of our lives. No creature has drawn more praise and more abuse than the ordinary garden snail. Cooked in wine, snails are a great luxury in some countries, and there are people who, ever since their earliest years, have learned to think of them as food. My friend Robert has loved snails for as long as I have known him. As he lives in an apartment in a big city, he has no garden of his own, and for years he has been asking me to gather snails from mine. One day, after a heavy shower, I happened to be walking outside when I noticed dozens of snails crawling over my prize plants. On a sudden impulse, I collected several dozen, dropped them into a paper bag, and drove them over to Robert. He was delighted. I set the bag down in the hall, and we chatted for a couple of hours. I had completely forgotten the snails until Robert insisted I stay for dinner, snails, of course, being the main dish. When we walked back to the hall, we froze: the snails had escaped and taken over the entire hallway. I have never been able to look at a snail the same way since.","explanation_cn":"课文说 we froze…they had taken over the hall——看到蜗牛占满走廊,作者惊愕沮丧。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l24',3,5,24,'A Skeleton in the Closet','家丑','频率副词(often/always/rarely/never)的位置、few / a few / little / a little 的区别、形容词 + 固定介词(proud of / afraid of / aware of / familiar with)、使役动词 make / let + 某人/某物 + 动词原形、tell / want / allow sb to do 与直接引语的引号用法(原创承载 NCE3 L24 考点·轻净化:把小说例子里''毒死五任丈夫''改成''年轻时偷偷跑去马戏团跳舞''的无害家丑·侦探小说家客房壁橱里挂着他学医时的骨架 Sebastian)','我们常在小说里读到:一个看似体面的人或家庭,藏着一个瞒了外人多年的可怕秘密。英语里有个生动的说法来形容这种事——这秘密叫“壁橱里的骷髅”(家丑)。到了故事某个戏剧性的时刻,秘密曝光,名声就此毁掉。读者读到最后一页会毛骨悚然:原来那位一向和蔼可亲的女主人公——一位人人称道的老太太——年轻时竟偷偷跑去马戏团跳过舞。这种事发生在小说里当然无妨。多多少少,我们都有些不愿让密友知道的秘密,可真有“家丑”骨架的人却极少。我认识的唯一一个,是乔治·卡尔顿,而他还为此得意得很。乔治年轻时学医,后来没当医生,却成了写侦探小说的高手。有一次我在他家过了个终生难忘的周末。乔治把我领到客房,说这屋子很少用,让我把东西取出来就下楼吃饭。我把衬衫叠进抽屉后,想把一套西装挂进壁橱。一开门,我僵住了,吓呆了:一具骷髅就吊在眼前!门一动,它晃了起来,仿佛要朝我扑过来。我扔下西装,冲下楼去。乔治却毫不同情,笑着说,像在谈一位老朋友:“哦,那个啊。那是塞巴斯蒂安。你忘了我当年学过医啦。”','{"q":"Listen and answer — Who was Sebastian?","options":["George''s old medical-school skeleton","George''s brother","A famous detective","The writer''s friend"],"answer_index":0}'::jsonb,'{"title":"频率副词位置 / few·little / 形容词+介词 / make·let sb do","intro":"①频率副词(often, always, usually, rarely, never)一般放在实义动词前、be 动词或第一个助动词之后:We often read… / She had always been kind.②few / a few 修饰可数名词(few = 很少、几乎没有;a few = 一些);little / a little 修饰不可数名词。③许多形容词有固定介词:proud of、afraid of、aware of、familiar with、different from。④使役动词 make / let + 某人/某物 + 动词原形(不带 to):made it sway / let me go。⑤tell / want / allow sb to do 用带 to 的不定式;直接引语要用引号。","table":{"headers":["用法","意思","例子"],"rows":[["频率副词位置","实义动词前 / be 后","We often read… / had always been…"],["few / a few · little / a little","很少/一些(可数·不可数)","few of us / a little light"],["形容词 + 介词","固定搭配","proud of / afraid of / familiar with"],["make/let sb do · tell sb to do","使…做 / 让…做 / 叫…做","made it sway / told me to unpack"]]},"specialRules":[{"rule":"make / let 后面接动词原形(不带 to):made it sway(✓)made it to sway(✗);但 tell / want / allow sb 后面用带 to 的不定式:told me to go。","mark":"make sb do / tell sb to do"},{"rule":"few / little 表“几乎没有”(偏否定);a few / a little 表“一些”(偏肯定)。可数用 few / a few,不可数用 little / a little。","mark":"few / a few / little / a little"},{"rule":"美式习语与用词:a skeleton in the closet(英式 cupboard);closet 壁橱(英式 cupboard/wardrobe)。本课已按美语写。","mark":"closet / skeleton in the closet"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l24',1,NULL,'We often read in novels how a seemingly respectable person or family hides some terrible secret that has been kept from strangers for years. English has a vivid phrase for this kind of thing: the secret is called ''a skeleton in the closet.''','我们常在小说里读到:一个看似体面的人或家庭,藏着一个瞒了外人多年的可怕秘密。英语里有个生动的说法来形容这种事——这秘密叫“壁橱里的骷髅”(家丑)。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l24',2,NULL,'At some dramatic moment in the story, the secret comes out and a reputation is ruined. The reader''s hair stands on end when he learns, on the final page, that the heroine, a dear old lady who had always been so kind to everyone, had, in her youth, secretly run away to dance in a traveling circus.','到了故事某个戏剧性的时刻,秘密曝光,名声就此毁掉。读者读到最后一页会毛骨悚然:原来那位一向和蔼可亲的女主人公——一位人人称道的老太太——年轻时竟偷偷跑去马戏团跳过舞。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l24',3,NULL,'It is all very well for such things to happen in fiction. To varying degrees, we all keep secrets we would rather our closest friends never learn, but few of us have an actual skeleton in the closet. The only person I know who does is George Carlton, and he is very proud of the fact.','这种事发生在小说里当然无妨。多多少少,我们都有些不愿让密友知道的秘密,可真有“家丑”骨架的人却极少。我认识的唯一一个,是乔治·卡尔顿,而他还为此得意得很。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l24',4,NULL,'George studied medicine when he was young. Instead of becoming a doctor, however, he became a successful writer of detective stories. I once spent a weekend at his house that I shall never forget. George showed me to the guestroom, which, he said, was rarely used, and told me to unpack and come down to dinner.','乔治年轻时学医,后来没当医生,却成了写侦探小说的高手。有一次我在他家过了个终生难忘的周末。乔治把我领到客房,说这屋子很少用,让我把东西取出来就下楼吃饭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l24',5,NULL,'After I had stacked my shirts in a drawer, I went to hang a suit in the closet. I opened the door and froze, petrified: a skeleton was dangling right in front of me! The movement of the door made it sway, as if it were about to leap out at me. I dropped my suit and dashed downstairs. George was not at all sympathetic. ''Oh, that,'' he said with a smile. ''That''s Sebastian. You forget I was once a medical student.''','我把衬衫叠进抽屉后,想把一套西装挂进壁橱。一开门,我僵住了,吓呆了:一具骷髅就吊在眼前!门一动,它晃了起来,仿佛要朝我扑过来。我扔下西装,冲下楼去。乔治却毫不同情,笑着说:“哦,那个啊。那是塞巴斯蒂安。你忘了我当年学过医啦。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
