INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l24','a skeleton in the closet','a skeleton in the cupboard','家丑,不可告人的秘密;美语 in the closet,英式 in the cupboard') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
