INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l24','a skeleton in the closet','',NULL,'/ˈskelɪtn ɪn ðə ˈklɑːzɪt/','Every family has a skeleton in the closet.','家家都有本难念的经(都有家丑)。','He kept that skeleton in the closet for years.','那桩家丑他藏了好多年。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l24','one''s hair stands on end','',NULL,'/her stændz ɑːn end/','The ending made my hair stand on end.','那个结局让我毛骨悚然。','It was so scary my hair stood on end.','太吓人了,我汗毛都竖起来了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l24','be proud of','',NULL,'/praʊd əv/','George is proud of his skeleton.','乔治为他的骨架感到自豪。','She is proud of her work.','她为自己的工作感到自豪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l24','make sth do','',NULL,'/meɪk ˈsʌmθɪŋ duː/','The door made the skeleton sway.','门一动,骷髅就晃了起来。','The joke made everyone laugh.','那笑话把大家都逗笑了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp1','choice','{"stem":"下面哪一句 ''always'' 的位置正确?","options":["She had been always kind to everyone.","She had kind always been to everyone.","She had always been kind to everyone.","Always she had been kind to everyone she."],"answer_index":2,"stem_cn":"频率副词一般放在 be 动词或第一个助动词之后。","explanation_cn":"频率副词 always 放在第一个助动词 had 之后、been 之前。✓ She had always been kind. 其余三句 always 位置不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp1','choice','{"stem":"下面哪一句 ''often'' 的位置正确?","options":["We often read about family secrets.","We read about family often secrets.","Often read we about family secrets.","We often about read family secrets."],"answer_index":0,"stem_cn":"频率副词一般放在实义动词之前。","explanation_cn":"频率副词 often 放在实义动词 read 之前。✓ We often read about family secrets. 其余三句 often 位置乱放。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp1','choice','{"stem":"下面哪一句 ''rarely'' 的位置正确?","options":["The rarely guestroom was used.","The guestroom used rarely was.","Rarely the guestroom used was.","The guestroom was rarely used."],"answer_index":3,"stem_cn":"频率副词一般放在 be 动词之后。","explanation_cn":"频率副词 rarely 放在 be 动词 was 之后。✓ The guestroom was rarely used. 其余三句 rarely 位置不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp2','choice','{"stem":"\"___ of us have a real skeleton in the closet.\"(表“很少,几乎没有”,接可数)","options":["A few","Little","Few","A little"],"answer_index":2,"stem_cn":"我们当中很少有人真有“家丑”。","explanation_cn":"“很少、几乎没有”修饰可数名词用 few(偏否定)。✓ Few of us have a skeleton. ✗ A few(一些)/ Little(修饰不可数)/ A little:这里用 Few。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp2','choice','{"stem":"\"George gave me ___ good tips about writing.\"(表“一些”,接可数)","options":["a few","a little","little","few"],"answer_index":0,"stem_cn":"乔治给了我一些关于写作的好建议。","explanation_cn":"“一些”修饰可数名词用 a few(偏肯定)。✓ a few good tips. ✗ few(几乎没有)/ little / a little(修饰不可数):这里用 a few。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp2','choice','{"stem":"\"There was ___ light in the guestroom, so I could hardly see.\"(表“几乎没有”,接不可数)","options":["a few","a little","little","few"],"answer_index":2,"stem_cn":"客房里几乎没有光,我几乎看不见。","explanation_cn":"“几乎没有”修饰不可数名词(light)用 little。✓ little light in the room. ✗ a little(一点)/ few / a few(修饰可数):不可数、偏否定用 little。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp3','choice','{"stem":"\"George is very proud ___ his strange skeleton.\"(proud 后接哪个介词)","options":["for","to","with","of"],"answer_index":3,"stem_cn":"乔治为他那具怪骷髅感到很自豪。","explanation_cn":"be proud of“为…感到自豪”,介词固定用 of。✓ proud of his skeleton. ✗ with / for / to:proud 搭配 of。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp3','choice','{"stem":"\"At first I was afraid ___ the thing in the closet.\"(afraid 后接哪个介词)","options":["from","of","to","with"],"answer_index":1,"stem_cn":"起初我很怕壁橱里那东西。","explanation_cn":"be afraid of“害怕…”,介词用 of。✓ afraid of the thing in the closet. ✗ with / from / to:afraid 搭配 of。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp3','choice','{"stem":"\"I was not familiar ___ the layout of his house.\"(familiar 后接哪个介词)","options":["of","for","with","to"],"answer_index":2,"stem_cn":"我不熟悉他家的布局。","explanation_cn":"be familiar with“熟悉…”,介词用 with。✓ familiar with the layout. ✗ of / to / for:familiar 搭配 with(familiar to sb 是“为某人所熟悉”,方向不同)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp4','choice','{"stem":"\"The movement of the door made the skeleton ___.\"(make sb/sth + 动词原形)","options":["swaying","sway","swayed","to sway"],"answer_index":1,"stem_cn":"门一动,骷髅就晃了起来。","explanation_cn":"使役动词 make + 某物 + 动词原形(不带 to)。✓ made the skeleton sway. ✗ to sway / swaying / swayed:make 后接动词原形。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp4','choice','{"stem":"\"George would not let me ___ before I heard the whole story.\"(let sb + 动词原形)","options":["leave","to leave","left","leaving"],"answer_index":0,"stem_cn":"没听完整个故事,乔治不让我走。","explanation_cn":"使役动词 let + 某人 + 动词原形。✓ let me leave. ✗ to leave / leaving / left:let 后接动词原形。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp4','choice','{"stem":"\"The scare made me ___ downstairs at once.\"(make sb + 动词原形)","options":["dashed","dashing","dash","to dash"],"answer_index":2,"stem_cn":"一惊之下我立刻冲下了楼。","explanation_cn":"使役动词 make + 某人 + 动词原形。✓ made me dash downstairs. ✗ to dash / dashing / dashed:make 后接动词原形。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp5','choice','{"stem":"\"George told me ___ my things and come down.\"(tell sb + 不定式)","options":["to unpack","unpacking","unpacked","unpack"],"answer_index":0,"stem_cn":"乔治叫我把东西取出来,然后下楼。","explanation_cn":"tell sb to do sth,用带 to 的不定式。✓ told me to unpack. ✗ unpack / unpacking / unpacked:tell sb 后用 to do。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp5','choice','{"stem":"\"He did not allow the maid ___ the guestroom often.\"(allow sb + 不定式)","options":["cleaning","to clean","clean","cleaned"],"answer_index":1,"stem_cn":"他不让女佣常打扫客房。","explanation_cn":"allow sb to do sth,用带 to 的不定式。✓ allow the maid to clean. ✗ clean / cleaning / cleaned:allow sb 后用 to do。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp5','choice','{"stem":"下面哪一句直接引语的引号用得正确?","options":["That''s Sebastian, ''he said.''","That''s ''Sebastian,'' he said.","''That''s Sebastian he said.''","''That''s Sebastian,'' he said."],"answer_index":3,"stem_cn":"直接引语要用引号把说的话括起来。","explanation_cn":"直接引语用引号把说的话括起来,逗号放在引号内、he said 前。✓ ''That''s Sebastian,'' he said. 其余三句引号位置错误。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp6','choice','{"stem":"\"The bony frame inside a body is a ___.\"(“骷髅,骨架”用哪个词)","options":["shadow","skeleton","muscle","statue"],"answer_index":1,"stem_cn":"身体里的骨头架子。","explanation_cn":"身体里的骨头架子是 skeleton(骷髅、骨架)。✓ a skeleton in the closet. ✗ muscle 肌肉;✗ shadow 影子;✗ statue 雕像——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp6','choice','{"stem":"\"To hide something so no one finds it is to ___ it.\"(“隐藏”用哪个词)","options":["sell","reveal","conceal","announce"],"answer_index":2,"stem_cn":"把某物藏起来不让人发现。","explanation_cn":"把某物藏起来不让人发现用 conceal(隐藏)。✓ a secret concealed for years. ✗ reveal 揭露(相反);✗ announce 宣布;✗ sell 卖——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',5,'am3_l24_gp6','choice','{"stem":"\"To be so shocked that you cannot move is to be ___.\"(“惊呆”用哪个词)","options":["amused","relaxed","delighted","petrified"],"answer_index":3,"stem_cn":"吓得动弹不得。","explanation_cn":"吓得动弹不得是 petrified(惊呆的)。✓ I stood there petrified. ✗ delighted 高兴;✗ relaxed 放松;✗ amused 觉得好笑——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"skeleton 的意思是:","options":["影子","雕像","骷髅,骨架","肌肉"],"answer_index":2,"explanation_cn":"skeleton = 骷髅、骨架。✓ a skeleton in the closet 家丑。\n顺带记:肌肉 = muscle;影子 = shadow;雕像 = statue."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"conceal 的意思是:","options":["丢弃","隐藏,隐瞒","宣布","展示"],"answer_index":1,"explanation_cn":"conceal = 隐藏、隐瞒。✓ a secret concealed for years 藏了多年的秘密。\n顺带记:展示 = display;宣布 = announce;丢弃 = throw away."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"respectable 的意思是:","options":["贫穷的","可疑的","危险的","体面的,雅观的"],"answer_index":3,"explanation_cn":"respectable = 体面的、雅观的。✓ a respectable family 体面人家。\n顺带记:可疑的 = suspicious;贫穷的 = poor;危险的 = dangerous."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"petrify 的意思是:","options":["使高兴","使放松","使惊呆","使入睡"],"answer_index":2,"explanation_cn":"petrify = 使惊呆。✓ I stood there petrified 我吓呆了。\n顺带记:使高兴 = please;使放松 = relax;使入睡 = send to sleep."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"dangle 的意思是:","options":["躺下","悬挂,晃荡","漂浮","奔跑"],"answer_index":1,"explanation_cn":"dangle = 悬挂、晃荡。✓ a skeleton was dangling 一具骷髅吊着晃。\n顺带记:躺下 = lie down;奔跑 = run;漂浮 = float."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',6,NULL,'choice','{"stem":"unsympathetic 的意思是:","options":["不表同情的","慷慨的","热心的","诚实的"],"answer_index":0,"explanation_cn":"unsympathetic = 不表同情的。✓ George was unsympathetic 乔治毫不同情。\n顺带记:热心的 = warm-hearted;慷慨的 = generous;诚实的 = honest."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',7,NULL,'cloze','{"stem":"第 1 空","context":"English has a vivid phrase for a shameful secret: ''a skeleton in the closet.'' ___1___ of us really have one, but George does, and he is proud ___2___ it. When I opened his guestroom closet, a real skeleton made me ___3___ with fear. George only smiled and told me ___4___ worry, since it was just his old medical skeleton.","blank_no":1,"options":["Few","A few","Little","A little"],"answer_index":0,"explanation_cn":"“很少、几乎没有”修饰可数名词用 Few。✓ Few of us really have one."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',7,NULL,'cloze','{"stem":"第 2 空","context":"English has a vivid phrase for a shameful secret: ''a skeleton in the closet.'' ___1___ of us really have one, but George does, and he is proud ___2___ it. When I opened his guestroom closet, a real skeleton made me ___3___ with fear. George only smiled and told me ___4___ worry, since it was just his old medical skeleton.","blank_no":2,"options":["of","with","for","to"],"answer_index":0,"explanation_cn":"be proud of,介词用 of。✓ he is proud of it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',7,NULL,'cloze','{"stem":"第 3 空","context":"English has a vivid phrase for a shameful secret: ''a skeleton in the closet.'' ___1___ of us really have one, but George does, and he is proud ___2___ it. When I opened his guestroom closet, a real skeleton made me ___3___ with fear. George only smiled and told me ___4___ worry, since it was just his old medical skeleton.","blank_no":3,"options":["freeze","to freeze","freezing","froze"],"answer_index":0,"explanation_cn":"使役动词 make + 某人 + 动词原形。✓ a skeleton made me freeze."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',7,NULL,'cloze','{"stem":"第 4 空","context":"English has a vivid phrase for a shameful secret: ''a skeleton in the closet.'' ___1___ of us really have one, but George does, and he is proud ___2___ it. When I opened his guestroom closet, a real skeleton made me ___3___ with fear. George only smiled and told me ___4___ worry, since it was just his old medical skeleton.","blank_no":4,"options":["not to","to not","don''t","not"],"answer_index":0,"explanation_cn":"tell sb not to do sth,否定的不定式把 not 放在 to 前面。✓ told me not to worry."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',8,NULL,'choice','{"stem":"What does ''a skeleton in the closet'' mean?","options":["A shameful secret kept hidden","A real human skeleton","A medical model","A Halloween decoration"],"answer_index":0,"explanation_cn":"课文说 the secret is called ''a skeleton in the closet''——这个说法指藏起来的家丑。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',8,NULL,'choice','{"stem":"Why did George have a real skeleton?","options":["He found it in the house","He was a working doctor","He had studied medicine","He collected old bones"],"answer_index":2,"explanation_cn":"课文说 You forget I was once a medical student——乔治学过医,所以家里有骨架。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',8,NULL,'choice','{"stem":"How did the writer feel when he opened the closet?","options":["Delighted","Petrified","Merely curious","Bored"],"answer_index":1,"explanation_cn":"课文说 I opened the door and froze, petrified——开门看到骷髅时他吓呆了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',9,NULL,'choice','{"stem":"你想说\"我们当中很少有人真有''家丑''\"(few 表“很少”):","options":["Little of us have a real skeleton in the closet.","A few of us have a real skeleton in the closet.","Few of us have a real skeleton in the closet.","Few of us has a real skeleton in the closet."],"answer_index":2,"explanation_cn":"“很少、几乎没有”用 Few + 可数名词,后面动词用复数 have。✓ Few of us have a real skeleton in the closet. 场合:说“几乎没有人……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',9,NULL,'choice','{"stem":"你想说\"门一动,骷髅就晃了起来\"(make sth do):","options":["The movement of the door made the skeleton sway.","The movement of the door let the skeleton swayed.","The movement of the door made the skeleton to sway.","The movement of the door made the skeleton swaying."],"answer_index":0,"explanation_cn":"使役动词 make + 某物 + 动词原形(不带 to)。✓ The movement of the door made the skeleton sway. 场合:说某事使某物怎么样。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',9,NULL,'choice','{"stem":"你想说\"乔治为他的骷髅感到自豪\"(proud of):","options":["George is proud with his skeleton.","George is proud of his skeleton.","George is proud for his skeleton.","George is proud to his skeleton."],"answer_index":1,"explanation_cn":"be proud of,介词用 of。✓ George is proud of his skeleton. 场合:说某人为某事自豪。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"skeleton 的意思是:","options":["骷髅,骨架","雕像","肌肉","影子"],"answer_index":0,"explanation_cn":"skeleton = 骷髅、骨架。✓ a skeleton in the closet."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"conceal 的意思是:","options":["展示","丢弃","隐藏,隐瞒","宣布"],"answer_index":2,"explanation_cn":"conceal = 隐藏、隐瞒。✓ a secret concealed for years."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"\"The movement of the door made the skeleton ___.\"(make sth + 动词原形)","options":["swaying","sway","to sway","swayed"],"answer_index":1,"stem_cn":"门一动,骷髅就晃了起来。","explanation_cn":"使役动词 make + 某物 + 动词原形。✓ made the skeleton sway. ✗ to sway / swaying / swayed:make 后接原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"\"___ of us have a real skeleton in the closet.\"(表“很少”,接可数)","options":["A few","Little","A little","Few"],"answer_index":3,"stem_cn":"我们当中很少有人真有“家丑”。","explanation_cn":"“很少、几乎没有”修饰可数名词用 Few。✓ Few of us have a real skeleton. ✗ A few(一些)/ Little / A little(修饰不可数):这里用 Few。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"\"a skeleton in the closet\" 的意思是:","options":["家里的装饰","不可告人的家丑/秘密","医学模型","一副真骨架"],"answer_index":1,"explanation_cn":"a skeleton in the closet = 不可告人的家丑、秘密。✓ a skeleton in the closet 家丑。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"\"one''s hair stands on end\" 的意思是:","options":["理了新发型","兴奋得跳起来","头发乱了","吓得毛骨悚然"],"answer_index":3,"explanation_cn":"one''s hair stands on end = 吓得毛骨悚然。✓ my hair stood on end 我毛骨悚然。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"How did George react to the writer''s fright?","options":["He was unsympathetic and amused","He was frightened too","He apologized at once","He called a doctor"],"answer_index":0,"passage":"We often read in novels how a seemingly respectable person or family hides some terrible secret that has been kept from strangers for years. English has a vivid phrase for this kind of thing: the secret is called ''a skeleton in the closet.'' At some dramatic moment in the story, the secret comes out and a reputation is ruined. The reader''s hair stands on end when he learns, on the final page, that the heroine, a dear old lady who had always been so kind to everyone, had, in her youth, secretly run away to dance in a traveling circus. It is all very well for such things to happen in fiction. To varying degrees, we all keep secrets we would rather our closest friends never learn, but few of us have an actual skeleton in the closet. The only person I know who does is George Carlton, and he is very proud of the fact. George studied medicine when he was young. Instead of becoming a doctor, however, he became a successful writer of detective stories. I once spent a weekend at his house that I shall never forget. George showed me to the guestroom, which, he said, was rarely used, and told me to unpack and come down to dinner. After I had stacked my shirts in a drawer, I went to hang a suit in the closet. I opened the door and froze, petrified: a skeleton was dangling right in front of me! The movement of the door made it sway, as if it were about to leap out at me. I dropped my suit and dashed downstairs. George was not at all sympathetic. ''Oh, that,'' he said with a smile, as if speaking of an old friend. ''That''s Sebastian. You forget I was once a medical student.''","explanation_cn":"课文说 George was not at all sympathetic…said with a smile——乔治毫不同情,还笑着调侃。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"What did George become instead of a doctor?","options":["A teacher","A writer of detective stories","A surgeon","A painter"],"answer_index":1,"passage":"We often read in novels how a seemingly respectable person or family hides some terrible secret that has been kept from strangers for years. English has a vivid phrase for this kind of thing: the secret is called ''a skeleton in the closet.'' At some dramatic moment in the story, the secret comes out and a reputation is ruined. The reader''s hair stands on end when he learns, on the final page, that the heroine, a dear old lady who had always been so kind to everyone, had, in her youth, secretly run away to dance in a traveling circus. It is all very well for such things to happen in fiction. To varying degrees, we all keep secrets we would rather our closest friends never learn, but few of us have an actual skeleton in the closet. The only person I know who does is George Carlton, and he is very proud of the fact. George studied medicine when he was young. Instead of becoming a doctor, however, he became a successful writer of detective stories. I once spent a weekend at his house that I shall never forget. George showed me to the guestroom, which, he said, was rarely used, and told me to unpack and come down to dinner. After I had stacked my shirts in a drawer, I went to hang a suit in the closet. I opened the door and froze, petrified: a skeleton was dangling right in front of me! The movement of the door made it sway, as if it were about to leap out at me. I dropped my suit and dashed downstairs. George was not at all sympathetic. ''Oh, that,'' he said with a smile, as if speaking of an old friend. ''That''s Sebastian. You forget I was once a medical student.''","explanation_cn":"课文说 he became a successful writer of detective stories——乔治没当医生,成了侦探小说家。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"Who or what was ''Sebastian''?","options":["A ghost","A pet dog","George''s brother","George''s medical skeleton"],"answer_index":3,"audio":"We often read in novels how a seemingly respectable person or family hides some terrible secret that has been kept from strangers for years. English has a vivid phrase for this kind of thing: the secret is called ''a skeleton in the closet.'' At some dramatic moment in the story, the secret comes out and a reputation is ruined. The reader''s hair stands on end when he learns, on the final page, that the heroine, a dear old lady who had always been so kind to everyone, had, in her youth, secretly run away to dance in a traveling circus. It is all very well for such things to happen in fiction. To varying degrees, we all keep secrets we would rather our closest friends never learn, but few of us have an actual skeleton in the closet. The only person I know who does is George Carlton, and he is very proud of the fact. George studied medicine when he was young. Instead of becoming a doctor, however, he became a successful writer of detective stories. I once spent a weekend at his house that I shall never forget. George showed me to the guestroom, which, he said, was rarely used, and told me to unpack and come down to dinner. After I had stacked my shirts in a drawer, I went to hang a suit in the closet. I opened the door and froze, petrified: a skeleton was dangling right in front of me! The movement of the door made it sway, as if it were about to leap out at me. I dropped my suit and dashed downstairs. George was not at all sympathetic. ''Oh, that,'' he said with a smile, as if speaking of an old friend. ''That''s Sebastian. You forget I was once a medical student.''","explanation_cn":"课文说 ''That''s Sebastian. You forget I was once a medical student.''——塞巴斯蒂安是他学医时的骨架。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l24',10,NULL,'choice','{"stem":"What did George tell the writer to do when he first arrived?","options":["Unpack and come down to dinner","Lock the closet","Clean the room","Leave at once"],"answer_index":0,"audio":"We often read in novels how a seemingly respectable person or family hides some terrible secret that has been kept from strangers for years. English has a vivid phrase for this kind of thing: the secret is called ''a skeleton in the closet.'' At some dramatic moment in the story, the secret comes out and a reputation is ruined. The reader''s hair stands on end when he learns, on the final page, that the heroine, a dear old lady who had always been so kind to everyone, had, in her youth, secretly run away to dance in a traveling circus. It is all very well for such things to happen in fiction. To varying degrees, we all keep secrets we would rather our closest friends never learn, but few of us have an actual skeleton in the closet. The only person I know who does is George Carlton, and he is very proud of the fact. George studied medicine when he was young. Instead of becoming a doctor, however, he became a successful writer of detective stories. I once spent a weekend at his house that I shall never forget. George showed me to the guestroom, which, he said, was rarely used, and told me to unpack and come down to dinner. After I had stacked my shirts in a drawer, I went to hang a suit in the closet. I opened the door and froze, petrified: a skeleton was dangling right in front of me! The movement of the door made it sway, as if it were about to leap out at me. I dropped my suit and dashed downstairs. George was not at all sympathetic. ''Oh, that,'' he said with a smile, as if speaking of an old friend. ''That''s Sebastian. You forget I was once a medical student.''","explanation_cn":"课文说 told me to unpack and come down to dinner——乔治叫他取出东西、下楼吃饭。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
